async function channelMembership(api2, env, telegramId) {
  try {
    const member = await api2(env, "getChatMember", { chat_id: MEMBERSHIP_CHANNEL, user_id: Number(telegramId) });
    if (["creator", "administrator", "member"].includes(member?.status) || member?.status === "restricted" && member.is_member === true) return "member";
    if (["left", "kicked", "restricted"].includes(member?.status)) return "not_member";
  } catch {
  }
  return "unavailable";
}
