      value: labels[r.value] || String(r.value).replace(/ Stars/g, " \u0627\u0633\u062A\u0627\u0631").replace(/Unavailable/g, "\u0646\u0627\u0645\u0648\u062C\u0648\u062F").replace(/(\d+) days/g, "$1 \u0631\u0648\u0632").replace(/\b(active|annual|quarterly|trial|revoked|suspended)\b/g, (status) => labels[status])
