async function signalRecords(env, user) {
  const tv = (await env.DB.prepare("SELECT id,normalized_json,received_at FROM received_signals WHERE tenant_id=? ORDER BY received_at DESC LIMIT 20").bind(user.id).all()).results || [];
  const tg2 = (await env.DB.prepare("SELECT id,payload_json AS normalized_json,created_at AS received_at FROM commands WHERE tenant_id=? AND source_type='telegram' ORDER BY created_at DESC LIMIT 20").bind(user.id).all()).results || [];
  const rows2 = [...tv.map((r) => ({ ...r, source: "TradingView" })), ...tg2.map((r) => ({ ...r, source: "Telegram" }))];
  return rows2.map((r) => {
    try {
      const s = JSON.parse(r.normalized_json);
      if (s.action && s.action !== "OPEN") return null;
      if (!["BUY", "SELL"].includes(s.side) || !s.symbol || !s.order) return null;
      return { ...r, signal: s };
    } catch {
      return null;
    }
  }).filter(Boolean).sort((a, b) => b.received_at.replace("T", " ").localeCompare(a.received_at.replace("T", " ")) || b.id.localeCompare(a.id));
}
