async function opsScan(epoch){
 const counts={checked:0,online:0,demo:0,live:0,unknown_mode:0,unavailable:0};let cursor='',page,allClients=[];
 do{
  page=await api('/api/admin/connections?limit=20'+(cursor?'&cursor='+encodeURIComponent(cursor):''));if(!opsActive(epoch))return;
  for(const key of Object.keys(counts))counts[key]+=page.counts[key]||0;allClients.push(...page.clients);
  set('opsScanStatus',opsNum(counts.checked)+' '+opsText('accounts checked','حساب بررسی شد'));cursor=page.next_cursor;
  if(page.has_more&&!cursor)throw Error('INVALID_CONNECTION_PAGE');
 }while(page.has_more);
 if(!opsActive(epoch))return;
 const incomplete=counts.unavailable>0,display=(n)=>incomplete?(n?'≥ '+opsNum(n):'—'):opsNum(n);
 const metrics=$('miniAdminMetrics').children;metrics[2]?.querySelector('strong')?.replaceChildren(document.createTextNode(display(counts.online)));metrics[2]?.querySelector('small')?.replaceChildren(document.createTextNode(incomplete?opsText('Partial: some snapshots unavailable','ناقص: برخی اتصال‌ها قابل بررسی نیستند'):opsText('Fresh authenticated connections','اتصال‌های معتبر و تازه')));
 const stats=$('opsBridgeMetrics').children;stats[3]?.querySelector('b')?.replaceChildren(document.createTextNode(display(counts.demo)));stats[4]?.querySelector('b')?.replaceChildren(document.createTextNode(display(counts.live)));
 set('opsScanStatus',opsNum(counts.checked)+' '+opsText('checked','بررسی شد')+(incomplete?' · '+opsNum(counts.unavailable)+' '+opsText('unavailable','نامشخص'):''));
 const root=$('opsConnections');root.replaceChildren();
 for(const c of allClients){const row=opsNode('div',undefined,'ops-connection'),info=opsNode('div'),status=opsNode('span',c.online?opsText('Online','آنلاین'):c.available?opsText('Offline','آفلاین'):opsText('Unavailable','نامشخص'),'ops-dot-status');status.dataset.online=String(c.online);info.append(opsNode('b','MT5 #'+c.account_login),opsNode('small',c.account_server+(c.mode?' · '+c.mode:'')));row.append(info,status);root.append(row)}if(!allClients.length)opsEmpty(root,'No bound, active Signal Bridge accounts.','حساب متصل با لایسنس فعال وجود ندارد.');
}
async function loadMiniAdmin(){
 if(!opsActive()||opsBusy)return;const epoch=opsEpoch;opsBusy=true;clearTimeout(opsTimer);$('miniAdminRefresh').disabled=true;adminLanguage();
 opsNotice(opsText('Refreshing administration data…','در حال به‌روزرسانی اطلاعات مدیریت…'));
 try{const d=await api('/api/admin/overview');if(!opsActive(epoch))return;opsRenderOverview(d);await opsScan(epoch);if(!opsActive(epoch))return;opsNotice(opsText('Statistics refresh every 30 seconds while this panel is open.','آمار هنگام باز بودن پنل هر ۳۰ ثانیه به‌روز می‌شود.'));if(opsView==='customers')await opsLoadUsers();if(opsView==='orders')await opsLoadOrders()}
 catch(e){if(opsActive(epoch))opsNotice(window.DrFXI18N?.error?.(e,locale)??'Something went wrong. Try again.',true)}
 finally{if(opsActive(epoch)){opsBusy=false;$('miniAdminRefresh').disabled=false;opsTimer=setTimeout(loadMiniAdmin,30000)}}
}
