   for(const [value,label] of options){if(u.id===state.user.id&&['suspend','revoke_license'].includes(value))continue;const opt=opsNode('option',label);opt.value=value;select.append(opt)}
   select.addEventListener('change',()=>{login.hidden=!select.value.startsWith('grant_scalper_');button.disabled=!select.value});
