// src/member-analytics.mjs
var ANALYTICS_HTML = '\n<section id="sbAnalytics" class="sb-analytics" aria-labelledby="sbAnalyticsTitle" hidden>\n <header class="sba-heading">\n  <div><span class="sba-eyebrow">SIGNAL BRIDGE / TRADE INTELLIGENCE</span><h2 id="sbAnalyticsTitle">Trading Analytics</h2><p>Analyze broker-verified account performance and the execution trail of your own signals.</p></div>\n  <div class="sba-heading-actions"><span id="sbaStatus" class="sba-state">Waiting for your EA</span><button type="button" id="sbaRefresh">\u21BB Refresh</button><button type="button" id="sbaExport">\u2193 Export signals</button></div>\n </header>\n <div class="sba-scope" role="note"><b>Data integrity</b><span>Account P/L includes broker trades outside Signal Bridge. Signal outcomes are kept separate until individual broker deals can be linked to each signal. No simulated results.</span></div>\n <div class="sba-kpis" aria-label="Broker account performance">\n  <article><small>NET P/L \xB7 EA REPORT RANGE</small><strong id="sbaNet">\u2014</strong><span>Realized, after broker costs</span></article>\n  <article><small>GROSS PROFIT</small><strong id="sbaProfit">\u2014</strong><span>Broker account scope</span></article>\n  <article><small>GROSS LOSS</small><strong id="sbaLoss">\u2014</strong><span>Broker account scope</span></article>\n  <article><small>ACCOUNT BALANCE</small><strong id="sbaBalance">\u2014</strong><span>Live broker snapshot</span></article>\n  <article><small>ACCOUNT EQUITY</small><strong id="sbaEquity">\u2014</strong><span>Includes open positions</span></article>\n  <article><small>EA SIGNALS</small><strong id="sbaSignals">\u2014</strong><span>Selected EA report period</span></article>\n </div>\n <div class="sba-charts">\n  <section class="sba-card sba-main-chart" aria-labelledby="sbaTrendTitle">\n   <div class="sba-card-head"><div><h3 id="sbaTrendTitle">Realized P/L trend</h3><p>Last 14 broker days \xB7 cumulative net result, not account equity</p></div><div class="sba-segment" role="group" aria-label="Chart visualization"><button type="button" data-sba-mode="curve" aria-pressed="true">Curve</button><button type="button" data-sba-mode="daily" aria-pressed="false">Daily</button></div></div>\n   <div id="sbaPlot" role="img" class="sba-plot" aria-label="No verified P/L data"><p>Connect an updated Signal Bridge EA to load broker performance.</p></div>\n   <div class="sba-chart-footer"><span>Earlier broker day</span><span>14-day realized P/L \xB7 account currency</span><span>Latest broker day</span></div>\n  </section>\n  <section class="sba-card sba-route-card" aria-labelledby="sbaSignalsTitle"><div class="sba-card-head"><div><h3 id="sbaSignalsTitle">Signal delivery</h3><p>Last 60 commands \xB7 not a trade win-rate</p></div></div>\n   <div id="sbaDelivery" class="sba-delivery"><p>No recent signal commands available.</p></div><p id="sbaSourceCaption" class="sba-note">Sources: TradingView and Telegram. Execution status is reported separately from P/L.</p>\n  </section>\n </div>\n <section class="sba-card sba-calendar-card" aria-labelledby="sbaCalendarTitle"><div class="sba-card-head"><div><h3 id="sbaCalendarTitle">Performance calendar</h3><p>14-day verified net P/L \xB7 green gain / red loss / neutral zero</p></div><span class="sba-legend"><i class="gain"></i> Gain <i class="loss"></i> Loss <i class="flat"></i> Flat</span></div><div class="sba-calendar-scroll"><div id="sbaCalendar" class="sba-calendar"><p>Broker history is not yet available.</p></div></div></section>\n <section class="sba-card sba-hours-card" aria-labelledby="sbaHourTitle"><div class="sba-card-head"><div><h3 id="sbaHourTitle">Signals received per hour</h3><p>UTC \xB7 arrival timestamps of the latest 60 commands, NOT hourly trading profits</p></div></div><div id="sbaHours" class="sba-hours"></div></section>\n <div class="sba-charts sba-lower">\n  <section class="sba-card"><div class="sba-card-head"><div><h3>Advanced trade statistics</h3><p>Calculated from individual broker deals, not aggregate account totals</p></div></div><div class="sba-unavailable"><span class="sba-lock">\u23F3 Requires deal history</span><div class="sba-mini-metrics"><div><small>Win rate</small><b>\u2014</b></div><div><small>Average R/R</small><b>\u2014</b></div><div><small>Avg. win / loss</small><b>\u2014</b></div><div><small>Trade duration</small><b>\u2014</b></div><div><small>Win / loss streaks</small><b>\u2014</b></div><div><small>Max drawdown</small><b>\u2014</b></div></div><p>Requires closed-deal P/L, entry/exit times, fees, risk-at-entry and an auditable signal-to-position mapping. Until then these values remain unavailable.</p></div></section>\n  <section class="sba-card"><div class="sba-card-head"><div><h3>Session analytics &amp; Monte Carlo</h3><p>Asia \xB7 London \xB7 New York</p></div></div><div class="sba-unavailable"><span class="sba-lock">\u23F3 Requires deal history</span><p>Session win rate, risk/reward distributions, a full-year calendar, trade journal and Monte Carlo simulations will be enabled after sufficient verified trade-level history exists. Overlapping sessions and time zones must be calculated from trade timestamps.</p></div></section>\n </div>\n <section class="sba-card sba-history" aria-labelledby="sbaHistoryTitle"><div class="sba-card-head"><div><h3 id="sbaHistoryTitle">Your signal history</h3><p>Recent commands with their latest recorded execution statuses</p></div><label>Source <select id="sbaSource"><option value="all">All</option><option value="tradingview">TradingView</option><option value="telegram">Telegram</option><option value="test">Test</option></select></label></div><div class="sba-table-scroll"><table><thead><tr><th>UTC time</th><th>Source</th><th>Symbol</th><th>Side</th><th>Lots</th><th>Status</th></tr></thead><tbody id="sbaHistoryBody"><tr><td colspan="6">No signals yet</td></tr></tbody></table></div><p class="sba-note">Results cover only the latest 60 commands. A filled command is not necessarily a profitable closed trade. The data is visible only inside your authenticated account.</p></section>\n</section>';
var ANALYTICS_CSS = "\n#connectionActions.sb-tab-analytics .sb-command-heading,#connectionActions.sb-tab-analytics .sb-flight-path,#connectionActions.sb-tab-analytics .sb-kpis,#connectionActions.sb-tab-analytics .sb-grid,#connectionActions.sb-tab-analytics #executionFeedback,#connectionActions.sb-tab-analytics .ref-route-status,#connectionActions.sb-tab-analytics .sb-workspace-footer{display:none!important}\n#connectionActions .sb-analytics{color:#eaf0f9;min-width:0;padding:4px 0 24px;font-size:13px}\n#connectionActions .sb-analytics[hidden]{display:none!important}\n#connectionActions .sba-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:17px}\n#connectionActions .sba-heading h2{font-size:clamp(24px,2.6vw,34px)!important;letter-spacing:-.045em;font-weight:650;margin:3px 0 4px!important;line-height:1.2}\n#connectionActions .sba-heading p,#connectionActions .sba-card-head p{color:#93a8c1;font-size:12px;line-height:1.5;margin:3px 0}\n#connectionActions .sba-eyebrow{font-size:10px;letter-spacing:.14em;font-weight:700;color:#d4b778}\n#connectionActions .sba-heading-actions{display:flex;flex-wrap:wrap;align-items:center;gap:8px}\n#connectionActions .sba-state{display:inline-flex;align-items:center;border:1px solid #3c526c;border-radius:99px;padding:8px 12px;background:#152033;color:#b3c8df;font-size:11px}\n#connectionActions .sba-state[data-live=true]{border-color:#42826d;color:#8ee3bd;background:#143126}\n#connectionActions .sba-heading-actions button{min-height:35px;font-size:12px}\n#connectionActions .sba-scope{display:flex;gap:12px;padding:12px 15px;border:1px solid #49617b;border-radius:12px;background:#1a2639;margin-bottom:14px;color:#acbfd6;font-size:12px;line-height:1.5}\n#connectionActions .sba-scope b{white-space:nowrap;color:#f0d197}\n#connectionActions .sba-kpis{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:14px}\n#connectionActions .sba-kpis article{min-width:0;padding:15px 13px;display:flex;flex-direction:column;gap:8px;border:1px solid #2a3b52;border-radius:14px;background:linear-gradient(140deg,#1b283b,#131e2f)}\n#connectionActions .sba-kpis small{font-size:9px;letter-spacing:.06em;font-weight:700;color:#9caec4}\n#connectionActions .sba-kpis strong{font-size:clamp(18px,2vw,28px);font-weight:650;line-height:1.25;letter-spacing:-.045em;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n#connectionActions .sba-kpis article>span{font-size:10px;color:#90a5bd}\n#connectionActions .sba-positive{color:#6de0a5!important}#connectionActions .sba-negative{color:#f28b91!important}\n#connectionActions .sba-charts{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(300px,1fr);gap:14px;margin-bottom:14px}\n#connectionActions .sba-card{min-width:0;overflow:hidden;background:#202d41;border:1px solid #2d3e56;border-radius:16px;padding:20px;margin-bottom:14px}\n#connectionActions .sba-charts>.sba-card{margin-bottom:0}\n#connectionActions .sba-card-head{display:flex;justify-content:space-between;align-items:start;gap:12px;flex-wrap:wrap;margin-bottom:16px}\n#connectionActions .sba-card-head h3{font-size:16px!important;font-weight:650!important;letter-spacing:-.02em;margin:0!important;color:#eff3fa}\n#connectionActions .sba-segment{display:flex;border:1px solid #3b4e65;border-radius:99px;padding:3px;background:#152136;gap:3px}\n#connectionActions .sba-segment button{padding:5px 13px!important;min-height:28px;border-radius:99px;border:0!important;background:transparent;color:#a7bad0;font-size:11px}\n#connectionActions .sba-segment button[aria-pressed=true]{background:#33445b;color:#fff}\n#connectionActions .sba-plot{height:260px;display:flex;align-items:center;justify-content:center;color:#9fb2c9;font-size:12px}\n#connectionActions .sba-plot svg{height:100%;width:100%;display:block;overflow:visible}\n#connectionActions .sba-plot svg text{fill:#93a4b9;font:11px ui-monospace,monospace}\n#connectionActions .sba-plot svg .grid{stroke:#3b4d62;stroke-width:1}\n#connectionActions .sba-chart-footer{display:flex;justify-content:space-between;gap:9px;font-size:10px;color:#91a4bd;margin-top:9px}\n#connectionActions .sba-delivery{display:grid;gap:10px}\n#connectionActions .sba-delivery>div{display:grid;grid-template-columns:100px 1fr 30px;align-items:center;gap:10px;font-size:11px}\n#connectionActions .sba-delivery .track{height:9px;background:#344257;border-radius:99px;overflow:hidden}\n#connectionActions .sba-delivery .track i{display:block;height:100%;border-radius:99px;background:#56b9da}\n#connectionActions .sba-note{font-size:11px;color:#9eafc7;line-height:1.6;margin:12px 0 0}\n#connectionActions .sba-calendar-scroll{overflow-x:auto}\n#connectionActions .sba-calendar{display:grid;grid-template-columns:repeat(14,minmax(60px,1fr));min-width:750px;gap:5px}\n#connectionActions .sba-day{display:flex;min-height:73px;flex-direction:column;justify-content:space-between;padding:9px 6px;border-radius:9px;border:1px solid #39485d;background:#192637;text-align:center}\n#connectionActions .sba-day.gain{background:#1d7049;border-color:#429d69;color:#e0ffe9}\n#connectionActions .sba-day.loss{background:#7a2936;border-color:#a64c58;color:#ffe1e5}\n#connectionActions .sba-day.flat{color:#bac9dc}\n#connectionActions .sba-day small{font-size:10px;opacity:.8}\n#connectionActions .sba-day b{font-size:11px;font-variant-numeric:tabular-nums}\n#connectionActions .sba-legend{display:flex;gap:8px;align-items:center;font-size:10px;color:#c6d2e3;white-space:nowrap}\n#connectionActions .sba-legend i{width:8px;height:8px;border-radius:2px}\n#connectionActions .sba-legend .gain{background:#3fb374}.sba-legend .loss{background:#e06473}.sba-legend .flat{background:#a7aebf}\n#connectionActions .sba-hours{display:grid;grid-template-columns:repeat(24,minmax(19px,1fr));gap:4px;align-items:end;min-height:134px}\n#connectionActions .sba-hour{display:grid;grid-template-rows:16px 90px 16px;gap:4px;align-items:end;justify-items:center;font-size:9px;color:#91a8c1}\n#connectionActions .sba-hour i{display:block;width:70%;min-height:2px;border-radius:4px 4px 0 0;background:linear-gradient(#5cbad3,#3e648b)}\n#connectionActions .sba-hour b{font-weight:500;font-size:9px}\n#connectionActions .sba-unavailable{background:#18263a;border:1px dashed #4c607a;border-radius:10px;padding:16px}\n#connectionActions .sba-lock{display:inline-block;background:#3b3440;color:#e2c2ab;border-radius:100px;padding:7px 10px;font-size:11px}\n#connectionActions .sba-unavailable p{font-size:11px;color:#a6b9d1;line-height:1.7;margin:13px 0 0}\n#connectionActions .sba-mini-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:14px}\n#connectionActions .sba-mini-metrics>div{display:flex;flex-direction:column;gap:5px;padding:9px;border:1px solid #3b4e65;border-radius:9px}\n#connectionActions .sba-mini-metrics small{color:#a6b8ce;font-size:10px}\n#connectionActions .sba-mini-metrics b{font-size:19px}\n#connectionActions .sba-history label{font-size:11px;color:#a2b5cb}\n#connectionActions .sba-history select{margin-left:9px;min-height:36px;font-size:12px}\n#connectionActions .sba-table-scroll{overflow-x:auto;max-height:350px;overflow-y:auto}\n#connectionActions .sba-history table{width:100%;border-collapse:collapse;min-width:620px;font-size:12px}\n#connectionActions .sba-history th,#connectionActions .sba-history td{text-align:left;padding:11px;border-bottom:1px solid #3b4b60}\n#connectionActions .sba-history th{font-size:10px;letter-spacing:.05em;color:#a4b5c9;position:sticky;top:0;background:#202d41}\n#connectionActions .sba-history td{font-variant-numeric:tabular-nums;color:#dce6f3}\n@media(max-width:1150px){#connectionActions .sba-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}#connectionActions .sba-charts{grid-template-columns:1fr}}\n@media(max-width:700px){#connectionActions .sb-mobile-tabs{display:grid!important;grid-auto-flow:column;grid-auto-columns:minmax(57px,1fr);grid-template-columns:none!important;gap:0;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:thin}#connectionActions .sb-mobile-tabs button{min-width:0;padding:4px 2px;font-size:15px}#connectionActions .sb-mobile-tabs button span{font-size:9px}#connectionActions .sba-heading{align-items:start}#connectionActions .sba-heading-actions{width:100%}#connectionActions .sba-scope{flex-direction:column;gap:4px}#connectionActions .sba-kpis{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}#connectionActions .sba-kpis article{padding:12px 10px}#connectionActions .sba-card{padding:12px;margin-bottom:9px}#connectionActions .sba-plot{height:185px}#connectionActions .sba-chart-footer{font-size:9px}#connectionActions .sba-hours{overflow-x:auto;min-width:520px}#connectionActions .sba-hours-card{overflow-x:auto}#connectionActions .sba-mini-metrics{grid-template-columns:repeat(2,1fr)}}\n@media(prefers-reduced-motion:reduce){#connectionActions .sba-plot *{animation:none!important}}\n";
var ANALYTICS_JS = `
(function(){
 const root=document.getElementById('sbAnalytics');if(!root||root.dataset.mounted)return;root.dataset.mounted='true';
 const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
 let last=null,mode='curve';
 const n=v=>typeof v==='number'&&Number.isFinite(v)?v:null;
 const fmt=v=>n(v)===null?'\u2014':Number(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
 const money=v=>n(v)===null?'\u2014':(v<0?'\u2212':'')+fmt(Math.abs(v));
 const set=(id,v,kind)=>{const el=$(id);if(!el)return;el.textContent=kind==='int'?(n(v)===null?'\u2014':String(Math.trunc(v))):money(v);el.classList.toggle('sba-positive',n(v)!==null&&v>0&&kind!=='int');el.classList.toggle('sba-negative',n(v)!==null&&v<0&&kind!=='int')};
 const node=(tag,attrs={})=>{const e=document.createElementNS(NS,tag);for(const k in attrs)e.setAttribute(k,String(attrs[k]));return e};
 const addText=(svg,x,y,text)=>{const el=node('text',{x,y});el.textContent=text;svg.append(el)};
 const lineChart=series=>{const el=$('sbaPlot');el.replaceChildren();if(!series.length){const p=document.createElement('p');p.textContent='Verified daily broker P/L is unavailable. Connect your EA to enable this chart.';el.append(p);el.setAttribute('aria-label',p.textContent);return}
 const values=mode==='daily'?series:[0,...series.reduce((out,v)=>{out.push((out.length?out[out.length-1]:0)+v);return out},[])];
 const low=Math.min(0,...values),high=Math.max(0,...values),range=high-low||1;
 const x=i=>48+i/(values.length-1||1)*724,y=v=>214-(v-low)/range*176;
 const svg=node('svg',{viewBox:'0 0 820 245',preserveAspectRatio:'none',role:'img'});
 for(let i=0;i<5;i++){const v=low+range*i/4,yy=y(v);svg.append(node('line',{x1:44,y1:yy,x2:785,y2:yy,class:'grid'}));addText(svg,2,yy-5,String(Math.round(v*100)/100))}
 if(mode==='curve'){const d=values.map((v,i)=>(i?'L':'M')+x(i).toFixed(2)+' '+y(v).toFixed(2)).join(' ');const a=node('path',{d:d+' L'+x(values.length-1)+' '+y(0)+' L'+x(0)+' '+y(0)+' Z',fill:'#4597d1',opacity:'.16'});svg.append(a,node('line',{x1:44,y1:y(0),x2:785,y2:y(0),stroke:'#687b91','stroke-width':1}),node('path',{d,stroke:'#79afff','stroke-width':3,fill:'none','stroke-linejoin':'round','vector-effect':'non-scaling-stroke'}))}
 else{const bw=724/values.length*.65;values.forEach((v,i)=>{const cy=y(v);svg.append(node('rect',{x:x(i)-bw/2,y:Math.min(cy,y(0)),width:bw,height:Math.max(2,Math.abs(y(0)-cy)),fill:v>0?'#37b66f':v<0?'#cc5263':'#64748b',rx:3}))})}
 el.append(svg);el.setAttribute('aria-label',(mode==='curve'?'Cumulative ':'Daily ')+'broker account P/L, 14 days, final net '+fmt(series.reduce((a,b)=>a+b,0)))};
 function calendar(series){const box=$('sbaCalendar');box.replaceChildren();if(!series.length){const p=document.createElement('p');p.textContent='Waiting for broker P/L history';box.append(p);return}for(let i=0;i<series.length;i++){const v=series[i],d=document.createElement('div');d.className='sba-day '+(v>0?'gain':v<0?'loss':'flat');const day=document.createElement('small');day.textContent=i===series.length-1?'Latest':'Day \u2212'+(series.length-i-1);const val=document.createElement('b');val.textContent=(v>0?'+':'')+fmt(v);d.title='Broker day offset '+(series.length-i-1)+' \xB7 net P/L '+fmt(v);d.append(day,val);box.append(d)}}
 function hours(commands){const counts=Array(24).fill(0);for(const c of commands){const s=String(c.created_at||'').replace(' ','T');const t=Date.parse(s.endsWith('Z')?s:s+'Z');if(Number.isFinite(t))counts[new Date(t).getUTCHours()]++}const max=Math.max(1,...counts),box=$('sbaHours');box.replaceChildren();counts.forEach((v,i)=>{const col=document.createElement('div');col.className='sba-hour';const c=document.createElement('b');c.textContent=v;const bar=document.createElement('i');bar.style.height=Math.max(2,v/max*89)+'px';const label=document.createElement('span');label.textContent=String(i).padStart(2,'0');col.title=v+' commands received at '+label.textContent+':00 UTC (latest 60)';col.append(c,bar,label);box.append(col)})}
 function delivery(commands){const grouped={Filled:0,Submitted:0,Rejected:0,Other:0},totals={tradingview:0,telegram:0,test:0};for(const c of commands){const s=String(c.status||'').toUpperCase();if(s==='FILLED')grouped.Filled++;else if(s==='SUBMITTED'||s==='DELIVERED'||s==='PENDING')grouped.Submitted++;else if(['REJECTED','BROKER_REJECTED','ERROR','ACCOUNT_MISMATCH','EXPIRED'].includes(s))grouped.Rejected++;else grouped.Other++;if(c.source_type in totals)totals[c.source_type]++}
 const box=$('sbaDelivery');box.replaceChildren();if(!commands.length){const p=document.createElement('p');p.textContent='No recent commands available.';box.append(p);return}
 for(const [k,v] of Object.entries(grouped)){const row=document.createElement('div'),label=document.createElement('span'),track=document.createElement('span'),fill=document.createElement('i'),count=document.createElement('b');label.textContent=k;track.className='track';fill.style.width=(v/commands.length*100)+'%';if(k==='Rejected')fill.style.background='#e46c79';if(k==='Filled')fill.style.background='#48c98f';track.append(fill);count.textContent=v;row.append(label,track,count);box.append(row)}
 $('sbaSourceCaption').textContent='Source split in the latest '+commands.length+' commands: TradingView '+totals.tradingview+' \xB7 Telegram '+totals.telegram+' \xB7 Test '+totals.test+'. Filled \u2260 closed profitable trade.';}
 function history(commands){const value=$('sbaSource').value,box=$('sbaHistoryBody');box.replaceChildren();let selected=commands.filter(c=>value==='all'||c.source_type===value);
 for(const c of selected){const tr=document.createElement('tr');for(const item of [c.created_at||'\u2014',c.source_type||'\u2014',c.symbol||'\u2014',c.side||'\u2014',n(c.lots)===null?'\u2014':String(c.lots),c.status||'\u2014']){const td=document.createElement('td');td.textContent=String(item);tr.append(td)}box.append(tr)}
 if(!selected.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=6;td.textContent='No matching signals in the latest 60 commands';tr.append(td);box.append(tr)}}
 function update(detail){last=detail||{};const d=last.diagnostic||{},r=last.report||null,account=d.telemetry||{},online=!!d.terminal_online,verified=online&&!!r&&Array.isArray(r.series)&&r.series.length===14&&(d.capabilities||[]).includes('reports-v1'),series=verified&&r.series.every(v=>n(v)!==null)?r.series:[];
 const status=$('sbaStatus');status.dataset.live=String(verified);status.textContent=verified?'\u25CF Broker telemetry \xB7 '+String(account.mode||d.mt5_mode||'').toUpperCase():'\u25CB Waiting for broker-verified report';
 for(const [id,key] of [['sbaNet','net'],['sbaProfit','profit'],['sbaLoss','loss']])set(id,online?r?.[key]:null);
 set('sbaBalance',online?account.balance:null);set('sbaEquity',online?account.equity:null);set('sbaSignals',online?r?.signals:null,'int');
 lineChart(series);calendar(series);const commands=Array.isArray(last.commands)?last.commands.slice(0,60):[];delivery(commands);hours(commands);history(commands);
 }
 window.addEventListener('signalbridge-analytics-data',e=>update(e.detail));
 root.querySelectorAll('[data-sba-mode]').forEach(btn=>btn.addEventListener?.('click',()=>{mode=btn.dataset.sbaMode;root.querySelectorAll('[data-sba-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));update(last)}));
 $('sbaSource')?.addEventListener?.('change',()=>history(Array.isArray(last?.commands)?last.commands.slice(0,60):[]));
 $('sbaRefresh')?.addEventListener?.('click',()=>document.getElementById('workspaceRefresh')?.click());
 $('sbaExport')?.addEventListener?.('click',()=>{const commands=Array.isArray(last?.commands)?last.commands.slice(0,60):[];if(!commands.length)return;const cols=['created_at','source_type','symbol','side','lots','status'];const esc=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+\\-@\\t\\r]/,' $&')+'"';const csv=[cols.join(','),...commands.map(c=>cols.map(k=>esc(c[k])).join(','))].join('\\r\\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='signalbridge-recent-signals.csv';a.click();URL.revokeObjectURL(url)});
})();
`;

