const chip=c=>'<span class="pp-chip '+(bad(c)?'bad':good(c)?'good':'warn')+'">'+esc(label(c))+'</span>';
function report(){return product==='bridge'?diagnostic.telemetry?.report:null}
function graph(id,values){const box=$(id);box.classList.toggle('pp-chart-empty',!Array.isArray(values)||!values.length);if(!Array.isArray(values)||!values.length||!values.every(Number.isFinite)){box.innerHTML='<div class="pp-empty-chart"><span class="pp-empty-icon" aria-hidden="true">↗</span><div><strong>'+t('Your performance starts here','عملکرد معاملات شما از اینجا شروع می‌شود')+'</strong><p>'+t('Connect MetaTrader to see your verified broker history.','متاتریدر را برای مشاهدهٔ سابقهٔ معتبر بروکر متصل کنید.')+'</p><button type="button" data-pp-go="setup">'+t('Connect your EA →','اتصال EA ←')+'</button></div></div>';return}let total=0;const a=[0,...values.map(v=>total+=v)],lo=Math.min(...a),hi=Math.max(...a),span=hi-lo||1,x=i=>60+i/(a.length-1)*528,y=v=>178-(v-lo)/span*150;const path=a.map((v,i)=>(i?'L':'M')+x(i).toFixed(2)+' '+y(v).toFixed(2)).join(' ');box.innerHTML='<svg viewBox="0 0 600 210" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="'+id+'Fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#249aff" stop-opacity=".28"/><stop offset="1" stop-color="#249aff" stop-opacity=".01"/></linearGradient></defs>'+[0,1,2,3].map(i=>{const yy=28+i*50;return '<line x1="60" x2="588" y1="'+yy+'" y2="'+yy+'" stroke="#2a4052" stroke-width=".7"/><text x="52" y="'+(yy+4)+'" text-anchor="end" fill="#839db8">'+esc(new Intl.NumberFormat(document.documentElement.lang,{notation:'compact',maximumFractionDigits:1}).format(hi-span*i/3))+'</text>'}).join('')+'<path d="'+path+' L588 178 L60 178 Z" fill="url(#'+id+'Fill)"/><path d="'+path+'" fill="none" stroke="#44aafa" stroke-width="2.4" vector-effect="non-scaling-stroke"/><circle cx="588" cy="'+y(total)+'" r="3.5" fill="#a5deff"/><text x="60" y="201" fill="#839db8" font-size="10">'+esc(t('Oldest day','قدیمی‌ترین روز'))+'</text><text x="588" y="201" text-anchor="end" fill="#839db8" font-size="10">'+esc(t('Latest','آخرین روز'))+'</text><text x="585" y="18" text-anchor="end" fill="#99ccee" font-size="12">'+esc(cash(total))+'</text></svg>';box.setAttribute('aria-label',t('Cumulative broker P/L: ','سود و زیان تجمیعی بروکر: ')+cash(total));}
function connectionRows(){const enabled=[settings.tv_to_mt5!==false,!!settings.telegram_to_mt5,!!settings.tv_to_telegram],texts=['TradingView → MT5','Telegram → MT5','TradingView → Telegram'];$('ppConnections').innerHTML=texts.map((name,i)=>{const ready=product==='bridge'&&enabled[i]&&(i===0||settings.telegram_verified);const active=ready&&(i===2||diagnostic.terminal_online);const status=product!=='bridge'?t('Not supported','پشتیبانی نشده'):!enabled[i]?t('Off','خاموش'):i>0&&!settings.telegram_verified?t('Verify Telegram','تأیید تلگرام'):active?t('Active','فعال'):t('EA offline','EA آفلاین');return '<div class="pp-connection"><i>'+['TV','TG','TV'][i]+'</i><span>'+name+'</span><b class="pp-chip '+(active?'good':'')+'">'+status+'</b></div>'}).join('')}
function filtered(){if(product!=='bridge')return [];const q=$('ppSearch').value.trim().toLowerCase(),source=$('ppSource').value,today=$('ppDate').value==='today'?new Date().toISOString().slice(0,10):null;return records.filter(c=>(source==='all'||c.source_type===source)&&(!today||String(c.created_at).startsWith(today))&&(!q||[c.id,c.symbol,c.side,c.source_type,c.status].some(v=>String(v||'').toLowerCase().includes(q))))}
