var SETUP_HTML = `<section id="memberSetup" class="su-page" aria-labelledby="setupTitle" hidden>
 <header class="su-heading"><div><span class="sb-section-label" data-su="eyebrow">YOUR CONNECTION STUDIO</span><h2 id="setupTitle" data-su="title">Setup</h2><p data-su="intro">Three connections. One place to get started.</p></div><button type="button" id="setupRefresh" data-su="refresh">\u21BB Refresh</button></header>
 <section class="su-route-controls" aria-label="Signal routes"><h3>Your signal routes</h3><button type="button" id="setupTvMt5" role="switch" aria-checked="false">${mark("tradingview")}<b>TradingView \u2192 MT5</b><i class="su-destination">${mark("metatrader")}</i><small>Send TradingView alerts to MetaTrader 5 via SignalBridge EA</small><span>Checking</span></button><button type="button" id="setupTvTelegram" role="switch" aria-checked="false">${mark("tradingview")}<b>TradingView \u2192 Telegram</b><i class="su-destination">${mark("telegram")}</i><small>Send TradingView alerts to your Telegram channel</small><span>Checking</span></button><button type="button" id="setupTelegramEnable" role="switch" aria-checked="false">${mark("telegram")}<b>Telegram \u2192 MT5</b><i class="su-destination">${mark("metatrader")}</i><small>Forward Telegram signals to MetaTrader 5 via SignalBridge EA</small><span>Checking</span></button><p id="setupTelegramRouteStatus" role="status">Routes require a connected EA and verified Telegram account.</p></section>
 <div class="su-progress-head"><span id="setupProgress">0 / 3 configured</span><span data-su="progressHint">Your keys stay private</span></div>
 <div class="su-path" aria-label="Quick setup steps">
 <button type="button" data-setup-step="setupStep1" aria-pressed="true">${mark("metatrader")}<span><b data-su="navMt5">Install EA</b><small id="setupMt5State">Check terminal</small></span><em>01</em></button>
 <button type="button" data-setup-step="setupStep2" aria-pressed="false">${mark("tradingview")}<span><b>TradingView</b><small id="setupTvState">Get webhook</small></span><em>02</em></button>
 <button type="button" data-setup-step="setupStep3" aria-pressed="false">${mark("telegram")}<span><b>Telegram</b><small id="setupTgState">Pick channel</small></span><em>03</em></button></div>
 <div class="su-coach"><span class="su-coach-icon" aria-hidden="true">\u2197</span><div><b id="setupNextTitle">Start with MetaTrader 5</b><span id="setupNextHint">Download the EA and paste your private license.</span></div><button type="button" id="setupNext" data-su="next">Start \u2192</button></div>
 <div class="su-grid">
 <article class="su-card su-install" id="setupStep1"><header>${mark("metatrader")}<div><small data-su="step1">01 \xB7 INSTALL & ACTIVATE</small><h3 data-su="install">MetaTrader 5</h3></div><button type="button" class="ref-service-help" aria-label="Open service setup guide">?</button></header>
 <div class="su-product"><div><b>SignalBridge EA</b><small id="setupEaVersion">Checking release\u2026</small></div><a id="setupBridgeDownload" aria-disabled="true" data-su="download">Download EX5 \u2193</a></div>
 <label for="setupLicense" data-su="license">1 \xB7 EA license \xB7 paste in the FIRST input</label><div class="su-copy"><input id="setupLicense" type="password" readonly autocomplete="off" aria-label="SignalBridge license"><button type="button" id="setupReveal" aria-pressed="false" data-su="show">Show</button><button type="button" data-su-copy="setupLicense" data-su="copy">Copy</button></div>
 <label data-su="symbol">2 \xB7 Broker symbol \xB7 SECOND input</label><div class="su-symbol"><strong dir="ltr">XAUUSD</strong><span data-su="example">Example: XAUUSD.p or GOLD</span></div>
 <p class="su-help" data-su="symbolHelp">F7 \u2192 Inputs: paste your license first; then enter the exact gold symbol shown in Market Watch.</p>
 <div class="su-product su-scalper"><div><b>DrFX Scalper Pro</b><small data-su="scalperHint">Separate EA \xB7 separate license</small></div><a id="setupScalperDownload" aria-disabled="true" data-su="download">Download EX5 \u2193</a></div>
 <details class="ref-scalper-licenses"><summary>Scalper Pro license</summary><div id="setupScalperKeys" class="su-keys"></div></details>
 <details><summary data-su="installHelp">Where do I install the EX5?</summary><ol><li data-su="install1">MT5 desktop \u2192 File \u2192 Open Data Folder \u2192 MQL5 \u2192 Experts. Copy the EX5 here.</li><li data-su="install2">Navigator \u2192 Expert Advisors \u2192 Refresh. Drag the EA onto your broker's gold chart.</li><li data-su="install3">SignalBridge: F7 \u2192 Inputs \u2192 license, then symbol. Allow https://signalbridge.drfx.online in Tools \u2192 Options \u2192 Expert Advisors.</li><li data-su="installAlgo">EA Properties \u2192 Common \u2192 Allow algorithmic trading. Enable Algo Trading in the MT5 toolbar.</li><li data-su="install4">Scalper Pro: attach to an M15 gold chart. Start its trial or enter its own license. Keep MT5 running.</li></ol></details>
 </article>
 <article class="su-card" id="setupStep2"><header>${mark("tradingview")}<div><small data-su="step2">02 \xB7 CONNECT TRADINGVIEW</small><h3 data-su="webhookTitle">TradingView</h3></div><button type="button" class="ref-service-help" aria-label="Open service setup guide">?</button></header>
 <label for="setupMt5Hook" data-su="mt5Hook">Your personal MT5 webhook</label><div class="su-copy"><input id="setupMt5Hook" dir="ltr" readonly placeholder="\u2014" aria-label="Personal MT5 webhook"><button type="button" data-su-copy="setupMt5Hook" data-su="copy">Copy</button></div>
 <div class="su-buttons"><button id="setupCreateHook" type="button" data-su="create">Create webhook</button><span id="setupHookMode" class="sb-badge">\u2014</span><button id="setupExecutionMode" type="button" class="su-exec-mode" disabled title="Requires a personal webhook and explicit DEMO execution approval">Enable DEMO execution</button></div>
 <ol class="ref-tv-steps"><li>Open TradingView</li><li>Create an alert</li><li>Use your webhook URL above</li></ol><p class="su-help" data-su="hookHelp">TradingView \u2192 Create Alert \u2192 Notifications \u2192 Webhook URL. Paste this link for MT5 signals.</p>
 <details><summary data-su="tvGuide">TradingView setup guide</summary><ol><li data-su="tv1">Open your indicator or strategy chart and select Create Alert.</li><li data-su="tv2">Enable Webhook URL in Notifications; paste the link for your intended destination.</li><li data-su="tv3">Use your strategy's SignalBridge-compatible message. First check parsing and connection before enabling execution.</li></ol><p data-su="tvNote">Webhook availability depends on your TradingView account. Dry run receives alerts without placing orders; ordinary LIVE execution remains disabled.</p></details>
 <a class="su-create-alert" href="https://www.tradingview.com/chart/" target="_blank" rel="noopener">\u2197 Create alert</a><div class="su-check"><b data-su="checkTitle">Check your connection</b><p data-su="checkHint">Return to Daily view \u2192 Check connection. Green EA status confirms the terminal heartbeat.</p><button type="button" data-sb-tab="overview" data-su="daily">Open Daily view \u2197</button></div>
 </article>
 <article class="su-card" id="setupStep3"><header>${mark("telegram")}<div><small data-su="step3">03 \xB7 CHOOSE A CHANNEL</small><h3 data-su="channelTitle">Telegram</h3></div><button type="button" class="ref-service-help" aria-label="Open service setup guide">?</button></header>
 <div class="su-source-controls"><label for="setupSignalSource">Signal source</label><select id="setupSignalSource"><option value="private">Forward to this bot</option><option value="channel">My channel</option></select><label for="setupDefaultLots">Default lot size</label><input id="setupDefaultLots" type="number" min="0.01" max="100" step="0.01" value="0.01"><button type="button" id="setupSaveSource">Save signal source</button></div><p class="su-help" id="setupChannelHint" data-su="channelHint">Add the bot as a channel administrator with Post messages permission, then refresh.</p>
 <div class="su-buttons"><a id="setupAddBot" target="_blank" rel="noopener" hidden data-su="addBot">Add bot to channel \u2197</a><button id="setupChannelsRefresh" type="button" data-su="refresh">\u21BB Refresh</button></div>
 <label for="setupChannel" data-su="destination">Destination channel</label><select id="setupChannel"><option value="">\u2014</option></select>
 <button id="setupChannelCreate" type="button" disabled data-su="channelCreate">Get this channel's webhook</button>
 <label for="setupChannelHook" data-su="channelHook">Selected channel webhook \xB7 Telegram only</label><div class="su-copy"><input id="setupChannelHook" dir="ltr" readonly placeholder="\u2014" aria-label="Selected Telegram channel webhook"><button type="button" data-su-copy="setupChannelHook" data-su="copy">Copy</button></div>
 <details><summary data-su="channelGuide">How do alerts reach this channel?</summary><p data-su="channelGuideText">Copy the selected channel's webhook into a TradingView alert. This link posts messages to that channel only. It does not open MT5 trades. Select another channel to obtain its own link.</p><label for="setupChannelTemplate" data-su="template">TradingView message template</label><textarea id="setupChannelTemplate" readonly rows="3" dir="ltr"></textarea><button type="button" data-su-copy="setupChannelTemplate" data-su="copy">Copy</button></details>
 </article></div>
 <footer class="su-footer"><details class="su-more"><summary data-su="more">Account & advanced options</summary><div><button type="button" id="setupScalperManage" data-su="scalperManage">Scalper Pro \xB7 plans & licenses</button><button type="button" data-sb-tab="settings" data-su="advanced">Advanced, membership & administration</button><button type="button" data-sb-tab="routes" data-su="routing">Advanced signal routing</button></div></details><span id="setupStatus" role="status" aria-live="polite"></span></footer>
</section>`;
