  ru: { overview: "\u2302 \u041E\u0431\u0437\u043E\u0440", signals: "\u2637 \u0421\u0438\u0433\u043D\u0430\u043B\u044B", routes: "\u2667 \u041C\u0430\u0440\u0448\u0440\u0443\u0442\u044B", settings: "\u2699 \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438", received: "\u25F4 \u0421\u0438\u0433\u043D\u0430\u043B\u044B", profit: "\u2191 \u041F\u0440\u0438\u0431\u044B\u043B\u044C", loss: "\u2193 \u0423\u0431\u044B\u0442\u043E\u043A", net: "\u25A5 \u0427\u0438\u0441\u0442\u044B\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442", stops: "\u2715 \u0421\u0442\u043E\u043F\u044B", reset: "\u21BB \u0421\u0431\u0440\u043E\u0441 \u043E\u0442\u0447\u0451\u0442\u0430", stream: "\u25C9 \u041F\u043E\u0442\u043E\u043A \u0441\u0438\u0433\u043D\u0430\u043B\u043E\u0432", policy: "\u2699 \u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0434\u0435\u043B\u043A\u0430\u043C\u0438", risk: "\u2667 \u0414\u043D\u0435\u0432\u043D\u0430\u044F \u043F\u0440\u043E\u0441\u0430\u0434\u043A\u0430 \u0441\u0447\u0451\u0442\u0430", routing: "\u2667 \u041C\u0430\u0440\u0448\u0440\u0443\u0442\u0438\u0437\u0430\u0446\u0438\u044F \u0441\u0438\u0433\u043D\u0430\u043B\u043E\u0432", tests: "\u2667 \u0421\u0432\u044F\u0437\u044C \u0438 \u0442\u0435\u0441\u0442", save: "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u043F\u0440\u0430\u0432\u0438\u043B\u0430", preview: "\u0422\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440" },
  hi: { overview: "\u2302 \u0905\u0935\u0932\u094B\u0915\u0928", signals: "\u2637 \u0938\u0902\u0915\u0947\u0924", routes: "\u2667 \u092E\u093E\u0930\u094D\u0917", settings: "\u2699 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938", received: "\u25F4 \u0938\u0902\u0915\u0947\u0924", profit: "\u2191 \u0932\u093E\u092D", loss: "\u2193 \u0939\u093E\u0928\u093F", net: "\u25A5 \u0936\u0941\u0926\u094D\u0927 \u0932\u093E\u092D/\u0939\u093E\u0928\u093F", stops: "\u2715 \u0938\u094D\u091F\u0949\u092A", reset: "\u21BB \u0930\u093F\u092A\u094B\u0930\u094D\u091F \u0930\u0940\u0938\u0947\u091F", stream: "\u25C9 \u0932\u093E\u0907\u0935 \u0938\u0902\u0915\u0947\u0924", policy: "\u2699 \u091F\u094D\u0930\u0947\u0921 \u092A\u094D\u0930\u092C\u0902\u0927\u0928", risk: "\u2667 \u0916\u093E\u0924\u0947 \u0915\u093E \u0926\u0948\u0928\u093F\u0915 \u0921\u094D\u0930\u0949\u0921\u093E\u0909\u0928", routing: "\u2667 \u0938\u0902\u0915\u0947\u0924 \u0930\u0942\u091F\u093F\u0902\u0917", tests: "\u2667 \u0915\u0928\u0947\u0915\u094D\u0936\u0928 \u0914\u0930 \u092A\u0930\u0940\u0915\u094D\u0937\u0923", save: "\u0928\u0940\u0924\u093F \u0938\u0939\u0947\u091C\u0947\u0902", preview: "\u0915\u0947\u0935\u0932 \u092A\u0942\u0930\u094D\u0935\u093E\u0935\u0932\u094B\u0915\u0928" }
