var IDENTITY_LAYOUT_CSS = String.raw`
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
#authOverlay{padding:24px;align-items:center;overflow:hidden}
#authOverlay .dialog{box-sizing:border-box;width:min(440px,100%);max-height:calc(100dvh - 48px);overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;padding:30px;border:1px solid #36465b;border-radius:18px;background:radial-gradient(ellipse at top right,#22304766,transparent 60%),#0d1521;box-shadow:0 30px 100px #0009;font-family:"Plus Jakarta Sans",Vazirmatn,system-ui,sans-serif}
#authOverlay .close{display:grid;place-items:center;top:16px;right:auto;inset-inline-end:16px;width:36px;height:36px;font-size:26px;line-height:1;border:1px solid #34445a;border-radius:9px;background:#162234;color:#b8c6d7}
#authOverlay .section-kicker{display:block;padding-inline-end:40px;font-size:10px;letter-spacing:.12em;line-height:1.6}
#authOverlay h2{font-size:28px;line-height:1.25;font-weight:600;letter-spacing:-.045em;margin:18px 0 8px;color:#f4f7fb}
#authOverlay h2+p{font-size:13px;line-height:1.65;margin:0 0 16px;color:#a9b7ca}
#authOverlay #serviceReadiness{padding:10px 12px;margin:0 0 16px;border-color:#8f744a66;background:#31281766;color:#d4bf96;font-size:11px;line-height:1.6;border-radius:9px}
#authOverlay .tabs{gap:4px;padding:4px;margin-bottom:18px;border:1px solid #2d3e53;border-radius:11px;background:#080f19}
#authOverlay .tabs button{padding:9px;min-height:40px;font-size:13px;border-radius:7px;background:transparent;color:#a8b8cc}
#authOverlay .tabs button.selected{background:#213148;color:#f0d59c;box-shadow:0 2px 6px #0004}
#authOverlay label{font-size:12px;font-weight:600;line-height:1.6;margin:14px 0 7px;color:#c3cfde}
#authOverlay input{box-sizing:border-box;width:100%;min-height:46px;padding:11px 13px;border-radius:9px;border:1px solid #3a4f69;font-family:inherit;font-size:16px;line-height:1.5;color:#edf4fc;background:#080f19}
#authOverlay input:focus{outline:2px solid #e7c47788;outline-offset:2px;border-color:#d0ad66}
#authOverlay .btn-wide{min-height:44px;padding:10px 12px;border-radius:9px;margin-top:12px;font-size:13px;font-weight:600;gap:5px}
#authOverlay .btn-gold{background:linear-gradient(115deg,#d9b568,#f0d79b);border-color:#e7ca8e;color:#21180b}
#authOverlay .btn-outline{background:#1b2b40;border-color:#4d607a;color:#e5edf8}
#authOverlay .input-second{padding-top:4px}
#authOverlay .telegram-login-guide{padding:14px;border:1px solid #8f744a66;border-radius:11px;background:linear-gradient(130deg,#332b1c66,#15203166)}
#authOverlay .telegram-login-guide>strong{font-size:13px;font-weight:600;line-height:1.6;color:#ecd29b}
#authOverlay .telegram-login-guide ol{font-size:12px;line-height:1.65;margin:8px 0 0;padding-inline-start:19px;color:#bfcbd9}
#authOverlay .telegram-login-guide li{padding:2px 0}
#authOverlay .login-help{margin-top:8px}#authOverlay .login-help summary{cursor:pointer;color:#c6b58e;font-size:11px;min-height:28px;display:list-item;list-style:disclosure-closed inside}#authOverlay .login-help[open] summary{list-style-type:disclosure-open}#authOverlay .telegram-login-guide code{font-size:12px}
#authOverlay .telegram-login-guide .login-code-warning{font-size:11px!important;line-height:1.6!important;margin:9px 0 0!important;color:#d2b895!important}
#authOverlay .telegram-bot-link{min-height:40px;padding:9px 10px;margin-top:12px;font-size:12px;font-weight:600;background:#e4c47e;border-radius:8px}
#authOverlay .code-hint{font-size:11px;line-height:1.6;margin:7px 0 0;color:#9eafc5}
#authOverlay .message{font-size:12px;line-height:1.6;margin-top:12px;min-height:0}
#authOverlay .message:empty{display:none}
@media(max-width:600px){#authOverlay{padding:16px max(12px,env(safe-area-inset-right)) max(16px,env(safe-area-inset-bottom)) max(12px,env(safe-area-inset-left))}#authOverlay .dialog{width:min(420px,100%);max-height:calc(100dvh - 32px);padding:24px 20px;margin:auto;border-radius:16px}#authOverlay h2{font-size:26px}#authOverlay .tabs button,#authOverlay .btn-wide{min-height:44px}#authOverlay .dialog input{font-size:16px}#authOverlay .close{top:12px;inset-inline-end:12px}}
@media(max-height:650px){#authOverlay .dialog{padding-block:20px}#authOverlay h2{font-size:24px;margin-top:12px}#authOverlay h2+p{margin-bottom:12px}}
`;
