var DESIGN_JS = "    /* 0. PRELOADER */\n    (function() {\n      const bar = document.getElementById('preloader-bar');\n      const pct = document.getElementById('preloader-pct');\n      const log = document.getElementById('preloader-log');\n      const preloader = document.getElementById('preloader');\n      const logs = ['INITIALIZING DESIGN...', 'PREPARING DISPLAY...', 'LOADING PRODUCT PREVIEW...', 'LOADING SIGNAL VISUALS...'];\n      let p = 0;\n      const timer = setInterval(() => {\n        p = Math.min(100, p + Math.floor(Math.random() * 20) + 10);\n        bar.style.width = p + '%';\n        pct.textContent = p.toString().padStart(2, '0') + '%';\n        log.textContent = logs[Math.min(logs.length - 1, Math.floor(p / 26))];\n        if (p === 100) {\n          clearInterval(timer);\n          setTimeout(() => preloader.classList.add('loaded'), 240);\n        }\n      }, 85);\n    })();\n\n    /* 1. PROCEDURAL WEB AUDIO SYNTHESIZER */\n    let audioCtx = null, audioEnabled = false;\n    function toggleAudioEngine() {\n      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n      audioEnabled = !audioEnabled;\n      document.getElementById('audio-icon').textContent = audioEnabled ? '\u{1F50A}' : '\u{1F507}';\n      document.getElementById('audio-label').textContent = audioEnabled ? 'AUDIO: ON' : 'AUDIO: OFF';\n      if (audioEnabled) { playSignalImpactSound(); showToast('Tactile Horology Audio Enabled'); }\n    }\n    function playTickSound(freq = 800) {\n      if (!audioEnabled || !audioCtx) return;\n      const osc = audioCtx.createOscillator(), gain = audioCtx.createGain();\n      osc.type = 'sine';\n      osc.frequency.setValueAtTime(freq, audioCtx.currentTime);\n      osc.frequency.exponentialRampToValueAtTime(120, audioCtx.currentTime + 0.035);\n      gain.gain.setValueAtTime(0.04, audioCtx.currentTime);\n      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.035);\n      osc.connect(gain); gain.connect(audioCtx.destination);\n      osc.start(); osc.stop(audioCtx.currentTime + 0.04);\n    }\n    function playSignalImpactSound() {\n      if (!audioEnabled || !audioCtx) return;\n      const osc = audioCtx.createOscillator(), gain = audioCtx.createGain();\n      osc.type = 'triangle';\n      osc.frequency.setValueAtTime(160, audioCtx.currentTime);\n      osc.frequency.exponentialRampToValueAtTime(48, audioCtx.currentTime + 0.22);\n      gain.gain.setValueAtTime(0.09, audioCtx.currentTime);\n      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.24);\n      osc.connect(gain); gain.connect(audioCtx.destination);\n      osc.start(); osc.stop(audioCtx.currentTime + 0.25);\n    }\n\n    /* 2. GLOBAL AMBIENT SHADER CANVAS (NO GRID LINES) */\n    const ambCanvas = document.getElementById('ambientShaderCanvas');\n    const ambCtx = ambCanvas.getContext('2d');\n    let pointerX = window.innerWidth * 0.5, pointerY = window.innerHeight * 0.3;\n    function resizeAmbCanvas() { ambCanvas.width = window.innerWidth; ambCanvas.height = window.innerHeight; }\n    window.addEventListener('resize', resizeAmbCanvas); resizeAmbCanvas();\n    window.addEventListener('mousemove', e => { pointerX = e.clientX; pointerY = e.clientY; });\n    function renderAmbientShader() {\n      ambCtx.clearRect(0, 0, ambCanvas.width, ambCanvas.height);\n      const grad = ambCtx.createRadialGradient(pointerX, pointerY, 10, pointerX, pointerY, 550);\n      grad.addColorStop(0, 'rgba(212, 175, 55, 0.045)');\n      grad.addColorStop(0.5, 'rgba(16, 185, 129, 0.015)');\n      grad.addColorStop(1, 'transparent');\n      ambCtx.fillStyle = grad;\n      ambCtx.fillRect(0, 0, ambCanvas.width, ambCanvas.height);\n      requestAnimationFrame(renderAmbientShader);\n    }\n    renderAmbientShader();\n\n    /* 3. CARD TILT & SCROLL REVEAL */\n    document.querySelectorAll('.cinema-card').forEach(card => {\n      card.addEventListener('mousemove', e => {\n        const rect = card.getBoundingClientRect();\n        const x = e.clientX - rect.left, y = e.clientY - rect.top;\n        card.style.setProperty('--mouse-x', `${x}px`);\n        card.style.setProperty('--mouse-y', `${y}px`);\n        if (card.classList.contains('tilt-card') && window.innerWidth > 1024) {\n          const rotY = ((x / rect.width) - 0.5) * 5, rotX = ((y / rect.height) - 0.5) * -5;\n          card.style.transform = `perspective(1100px) rotateX(${rotX}deg) rotateY(${rotY}deg) translateY(-4px)`;\n        }\n      });\n      card.addEventListener('mouseleave', () => { card.style.transform = 'perspective(1100px) rotateX(0deg) rotateY(0deg) translateY(0px)'; });\n    });\n    const revealObserver = new IntersectionObserver(entries => {\n      entries.forEach(entry => { if (entry.isIntersecting) entry.target.classList.add('active'); });\n    }, { threshold: 0.12 });\n    document.querySelectorAll('.reveal-cinema').forEach(el => revealObserver.observe(el));\n\n    /* 4. HERO PHOTON REACTOR ENGINE */\n    const sigCanvas = document.getElementById('signalEngineCanvas');\n    const sigCtx = sigCanvas.getContext('2d');\n    let activeSourceMode = 'ALL', packets = [], shockwaves = [], floatingTags = [], chronoAngle = 0;\n    function resizeSignalCanvas() {\n      const rect = sigCanvas.parentElement.getBoundingClientRect();\n      sigCanvas.width = rect.width * window.devicePixelRatio;\n      sigCanvas.height = rect.height * window.devicePixelRatio;\n      sigCtx.setTransform(window.devicePixelRatio, 0, 0, window.devicePixelRatio, 0, 0);\n    }\n    window.addEventListener('resize', resizeSignalCanvas); resizeSignalCanvas();\n\n    function getCubicBezierXY(t, p0, p1, p2, p3) {\n      const u = 1 - t;\n      return {\n        x: u*u*u*p0.x + 3*u*u*t*p1.x + 3*u*t*t*p2.x + t*t*t*p3.x,\n        y: u*u*u*p0.y + 3*u*u*t*p1.y + 3*u*t*t*p2.y + t*t*t*p3.y\n      };\n    }\n    function spawnSignalPacket() {\n      const source = activeSourceMode === 'ALL' ? (Math.random() > 0.48 ? 'TV' : 'TG') : activeSourceMode;\n      packets.push({ source, progress: 0, speed: 0.012 + Math.random() * 0.005, color: source === 'TV' ? '#22D3EE' : '#F7E7B4', edgeTriggered: false, history: [] });\n    }\n    setInterval(spawnSignalPacket, 850);\n\n    const sampleOrders = [\n      { text: 'XAUUSD BUY \xB7 PREVIEW', tag: 'ALERT \u2192 BRIDGE', ping: 'PREVIEW' },\n      { text: 'EURUSD SELL \xB7 PREVIEW', tag: 'SIGNAL ROUTING', ping: 'PREVIEW' },\n      { text: 'NAS100 BUY \xB7 PREVIEW', tag: 'MT5 CONNECTION', ping: 'PREVIEW' }\n    ];\n    function triggerManualSignalPulse() {\n      playSignalImpactSound();\n      for (let i = 0; i < 4; i++) setTimeout(spawnSignalPacket, i * 95);\n      const pick = sampleOrders[Math.floor(Math.random() * sampleOrders.length)];\n      document.getElementById('live-order-ticker').textContent = pick.text;\n      document.getElementById('live-order-ping').textContent = pick.ping;\n      document.getElementById('live-latency-top').textContent = pick.ping;\n    }\n    function setSignalSource(mode) {\n      playTickSound(850); activeSourceMode = mode;\n      ['all', 'tv', 'tg'].forEach(id => {\n        const btn = document.getElementById('src-' + id);\n        btn.className = id.toUpperCase() === mode\n          ? 'px-2.5 py-1 rounded-md text-[10px] font-mono uppercase tracking-wider bg-gold/25 text-gold-light border border-gold/50 transition-all'\n          : 'px-2.5 py-1 rounded-md text-[10px] font-mono uppercase tracking-wider bg-obsidian/80 text-slate-400 border border-white/10 hover:text-white transition-all';\n      });\n      triggerManualSignalPulse();\n    }\n\n    function renderSignalEngine() {\n      const w = sigCanvas.width / window.devicePixelRatio, h = sigCanvas.height / window.devicePixelRatio;\n      sigCtx.clearRect(0, 0, w, h);\n      const tvNode = { x: w * 0.15, y: h * 0.34 }, tgNode = { x: w * 0.15, y: h * 0.68 }, cfNode = { x: w * 0.52, y: h * 0.50 }, mtNode = { x: w * 0.86, y: h * 0.50 };\n\n      [[tvNode, cfNode, 'rgba(34,211,238,0.18)'], [tgNode, cfNode, 'rgba(247,231,180,0.18)'], [cfNode, mtNode, 'rgba(52,211,153,0.24)']].forEach(([p0, p3, col]) => {\n        const cx = (p0.x + p3.x) / 2;\n        sigCtx.beginPath(); sigCtx.moveTo(p0.x, p0.y); sigCtx.bezierCurveTo(cx, p0.y, cx, p3.y, p3.x, p3.y);\n        sigCtx.strokeStyle = col; sigCtx.lineWidth = 1.5; sigCtx.stroke();\n      });\n\n      sigCtx.save(); sigCtx.globalCompositeOperation = 'lighter';\n      for (let i = packets.length - 1; i >= 0; i--) {\n        const pkt = packets[i]; pkt.progress += pkt.speed;\n        let pos, activeColor;\n        if (pkt.progress < 0.5) {\n          const t = pkt.progress * 2, start = pkt.source === 'TV' ? tvNode : tgNode, cx = (start.x + cfNode.x) / 2;\n          pos = getCubicBezierXY(t, start, { x: cx, y: start.y }, { x: cx, y: cfNode.y }, cfNode);\n          activeColor = pkt.color;\n        } else {\n          if (!pkt.edgeTriggered) { pkt.edgeTriggered = true; shockwaves.push({ x: cfNode.x, y: cfNode.y, r: 8, maxR: 36, alpha: 0.9, color: '#D4AF37' }); }\n          const t = (pkt.progress - 0.5) * 2;\n          pos = { x: cfNode.x + (mtNode.x - cfNode.x) * t, y: cfNode.y };\n          activeColor = '#34D399';\n        }\n        pkt.history.unshift({ x: pos.x, y: pos.y });\n        if (pkt.history.length > 12) pkt.history.pop();\n        for (let j = 0; j < pkt.history.length - 1; j++) {\n          const ratio = 1 - j / pkt.history.length;\n          sigCtx.beginPath(); sigCtx.moveTo(pkt.history[j].x, pkt.history[j].y); sigCtx.lineTo(pkt.history[j+1].x, pkt.history[j+1].y);\n          sigCtx.strokeStyle = activeColor; sigCtx.globalAlpha = ratio * 0.85; sigCtx.lineWidth = ratio * 4; sigCtx.stroke();\n        }\n        sigCtx.globalAlpha = 1;\n        sigCtx.beginPath(); sigCtx.arc(pos.x, pos.y, 3.2, 0, Math.PI * 2); sigCtx.fillStyle = '#FFF'; sigCtx.fill();\n        if (pkt.progress >= 1) {\n          shockwaves.push({ x: mtNode.x, y: mtNode.y, r: 8, maxR: 40, alpha: 0.9, color: '#10B981' });\n          floatingTags.push({ x: mtNode.x - 10, y: mtNode.y - 24, text: sampleOrders[i % sampleOrders.length].tag, alpha: 1 });\n          packets.splice(i, 1);\n        }\n      }\n      for (let i = shockwaves.length - 1; i >= 0; i--) {\n        const sw = shockwaves[i]; sw.r += (sw.maxR - sw.r) * 0.14; sw.alpha -= 0.035;\n        if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }\n        sigCtx.beginPath(); sigCtx.arc(sw.x, sw.y, sw.r, 0, Math.PI * 2); sigCtx.strokeStyle = sw.color; sigCtx.globalAlpha = sw.alpha; sigCtx.stroke();\n      }\n      sigCtx.restore();\n\n      for (let i = floatingTags.length - 1; i >= 0; i--) {\n        const ft = floatingTags[i]; ft.y -= 0.5; ft.alpha -= 0.02;\n        if (ft.alpha <= 0) { floatingTags.splice(i, 1); continue; }\n        sigCtx.save(); sigCtx.globalAlpha = ft.alpha; sigCtx.font = '600 9px \"JetBrains Mono\"'; sigCtx.fillStyle = '#34D399'; sigCtx.textAlign = 'right'; sigCtx.fillText(ft.text, ft.x, ft.y); sigCtx.restore();\n      }\n\n      chronoAngle += 0.012;\n      sigCtx.save(); sigCtx.translate(cfNode.x, cfNode.y); sigCtx.rotate(chronoAngle);\n      sigCtx.beginPath(); sigCtx.arc(0, 0, 32, 0, Math.PI * 2); sigCtx.strokeStyle = 'rgba(212,175,55,0.4)'; sigCtx.setLineDash([4, 5]); sigCtx.stroke();\n      sigCtx.restore();\n\n      [[tvNode, 'TV', 'WEBHOOK', '#22D3EE'], [tgNode, 'TG', 'BOT API', '#F7E7B4'], [cfNode, 'EDGE', 'CLOUDFLARE', '#D4AF37'], [mtNode, 'MT5', '.EX5 CORE', '#10B981']].forEach(([pt, l, s, c]) => {\n        sigCtx.beginPath(); sigCtx.arc(pt.x, pt.y, 17, 0, Math.PI * 2); sigCtx.fillStyle = '#070A0F'; sigCtx.fill(); sigCtx.lineWidth = 1.6; sigCtx.strokeStyle = c; sigCtx.stroke();\n        sigCtx.fillStyle = '#FFF'; sigCtx.font = '700 10px \"JetBrains Mono\"'; sigCtx.textAlign = 'center'; sigCtx.fillText(l, pt.x, pt.y + 3.5);\n        sigCtx.fillStyle = '#94A3B8'; sigCtx.font = '500 8.5px \"JetBrains Mono\"'; sigCtx.fillText(s, pt.x, pt.y + 31);\n      });\n      requestAnimationFrame(renderSignalEngine);\n    }\n    renderSignalEngine();\n\n    /* 5. AUTHENTIC TRADINGVIEW OHLCV CANDLESTICK ENGINE */\n    const indCanvas = document.getElementById('indicatorWaveCanvas');\n    const indCtx = indCanvas.getContext('2d');\n    let activeIndicatorIndex = 0, liveTickPhase = 0;\n    const indicatorNames = ['DFX_LiquiditySweep_v3.ex5', 'DFX_OrderblockMatrix_Pro.ex5', 'DFX_KalmanVolatility_Bands.ex5'];\n\n    const baseMarketStructure = [\n      { o: 2742.1, h: 2743.4, l: 2741.6, c: 2743.1, v: 42 }, { o: 2743.1, h: 2744.2, l: 2742.8, c: 2743.9, v: 51 },\n      { o: 2743.9, h: 2744.1, l: 2742.2, c: 2742.5, v: 38 }, { o: 2742.5, h: 2743.0, l: 2741.1, c: 2741.4, v: 44 },\n      { o: 2741.4, h: 2742.6, l: 2740.9, c: 2742.3, v: 35 }, { o: 2742.3, h: 2745.1, l: 2742.1, c: 2744.8, v: 78 },\n      { o: 2744.8, h: 2747.6, l: 2744.5, c: 2747.2, v: 92 }, { o: 2747.2, h: 2747.5, l: 2745.4, c: 2745.8, v: 60 },\n      { o: 2745.8, h: 2746.4, l: 2744.1, c: 2744.5, v: 49 }, { o: 2744.5, h: 2745.2, l: 2743.2, c: 2743.6, v: 41 },\n      { o: 2743.6, h: 2744.9, l: 2743.1, c: 2744.7, v: 53 }, { o: 2744.7, h: 2746.8, l: 2744.4, c: 2746.5, v: 67 },\n      { o: 2746.5, h: 2747.65, l: 2745.9, c: 2746.1, v: 58 }, { o: 2746.1, h: 2746.4, l: 2744.6, c: 2744.9, v: 45 },\n      { o: 2744.9, h: 2745.5, l: 2743.8, c: 2744.2, v: 39 }, { o: 2744.2, h: 2746.2, l: 2744.0, c: 2745.9, v: 61 },\n      { o: 2745.9, h: 2747.5, l: 2745.6, c: 2747.3, v: 74 }, { o: 2747.3, h: 2750.45, l: 2746.2, c: 2746.6, v: 118 },\n      { o: 2746.6, h: 2746.9, l: 2743.4, c: 2743.7, v: 104 }, { o: 2743.7, h: 2744.1, l: 2740.8, c: 2741.2, v: 96 },\n      { o: 2741.2, h: 2741.9, l: 2739.6, c: 2740.4, v: 72 }, { o: 2740.4, h: 2743.8, l: 2740.1, c: 2743.5, v: 110 },\n      { o: 2743.5, h: 2746.9, l: 2743.2, c: 2746.5, v: 105 }, { o: 2746.5, h: 2747.4, l: 2745.1, c: 2745.6, v: 54 },\n      { o: 2745.6, h: 2746.2, l: 2744.3, c: 2744.8, v: 48 }, { o: 2744.8, h: 2747.8, l: 2744.5, c: 2747.5, v: 88 },\n      { o: 2747.5, h: 2749.1, l: 2747.1, c: 2748.4, v: 79 }\n    ];\n\n    function selectIndicator(idx) {\n      playTickSound(920); activeIndicatorIndex = idx;\n      document.getElementById('indicator-title').textContent = indicatorNames[idx];\n      [0, 1, 2].forEach(i => {\n        document.getElementById('ind-btn-' + i).className = i === idx\n          ? 'px-2.5 py-1 rounded text-[10px] font-mono bg-gold text-obsidian font-semibold transition-all'\n          : 'px-2.5 py-1 rounded text-[10px] font-mono bg-white/5 text-slate-300 hover:bg-white/10 transition-all';\n      });\n    }\n\n    function renderIndicatorChart() {\n      const rect = indCanvas.getBoundingClientRect();\n      const pixelRatio = Math.min(window.devicePixelRatio || 1, 2);\n      const wpx = Math.round(rect.width * pixelRatio), hpx = Math.round(rect.height * pixelRatio);\n      if(indCanvas.width !== wpx || indCanvas.height !== hpx){\n        indCanvas.width = wpx; indCanvas.height = hpx;\n        indCtx.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);\n      }\n\n      const w = rect.width, h = rect.height, rightAxisW = 46, chartW = w - rightAxisW;\n      liveTickPhase += 0.045;\n      const liveOffset = Math.sin(liveTickPhase) * 0.45 + Math.cos(liveTickPhase * 2.3) * 0.25;\n      indCtx.clearRect(0, 0, w, h);\n\n      const minPrice = 2738.8, maxPrice = 2751.6;\n      const priceToY = p => h - 18 - ((p - minPrice) / (maxPrice - minPrice)) * (h - 30);\n\n      indCtx.fillStyle = '#64748B'; indCtx.font = '500 9px \"JetBrains Mono\"';\n      [2740.0, 2743.0, 2746.0, 2749.0].forEach(gp => {\n        const y = priceToY(gp);\n        indCtx.fillText(gp.toFixed(1), chartW + 4, y + 3);\n      });\n\n      const count = baseMarketStructure.length, step = chartW / (count + 1);\n\n      if (activeIndicatorIndex === 0) {\n        const bslY = priceToY(2747.65), xStart = 6 * step + step * 0.6, xEnd = 17 * step + step * 0.6, sweepTopY = priceToY(2750.45);\n        indCtx.fillStyle = 'rgba(212,175,55,0.09)'; indCtx.fillRect(xStart, sweepTopY, xEnd - xStart + 10, bslY - sweepTopY);\n        indCtx.save(); indCtx.setLineDash([4, 3]); indCtx.strokeStyle = '#D4AF37'; indCtx.beginPath(); indCtx.moveTo(xStart, bslY); indCtx.lineTo(xEnd + 12, bslY); indCtx.stroke(); indCtx.restore();\n        indCtx.fillStyle = '#F7E7B4'; indCtx.font = '600 8.5px \"JetBrains Mono\"'; indCtx.fillText('BSL LIQUIDITY POOL (2747.65)', xStart + 4, bslY - 4);\n      } else if (activeIndicatorIndex === 1) {\n        const fvg2Top = priceToY(2744.8), fvg2Bot = priceToY(2743.2), fvg2X = 21 * step + step * 0.6;\n        indCtx.fillStyle = 'rgba(38,166,154,0.18)'; indCtx.fillRect(fvg2X, fvg2Top, chartW - fvg2X, fvg2Bot - fvg2Top);\n        indCtx.strokeStyle = 'rgba(52,211,153,0.55)'; indCtx.strokeRect(fvg2X, fvg2Top, chartW - fvg2X, fvg2Bot - fvg2Top);\n        indCtx.fillStyle = '#34D399'; indCtx.font = '700 8.5px \"JetBrains Mono\"'; indCtx.fillText('BULLISH FVG (MITIGATED)', fvg2X + 4, fvg2Bot - 4);\n      } else {\n        let ema = baseMarketStructure[0].c;\n        const up = [], dn = [];\n        baseMarketStructure.forEach((b, i) => {\n          const c = i === count - 1 ? b.c + liveOffset : b.c;\n          ema = ema * 0.65 + c * 0.35;\n          const x = i * step + step * 0.6;\n          up.push({ x, y: priceToY(ema + 2.15) }); dn.push({ x, y: priceToY(ema - 2.15) });\n        });\n        indCtx.beginPath(); up.forEach((p, i) => i === 0 ? indCtx.moveTo(p.x, p.y) : indCtx.lineTo(p.x, p.y));\n        indCtx.strokeStyle = '#22D3EE'; indCtx.lineWidth = 1.4; indCtx.stroke();\n        indCtx.beginPath(); dn.forEach((p, i) => i === 0 ? indCtx.moveTo(p.x, p.y) : indCtx.lineTo(p.x, p.y));\n        indCtx.strokeStyle = 'rgba(34,211,238,0.5)'; indCtx.stroke();\n      }\n\n      const tvGreen = '#26A69A', tvRed = '#EF5350';\n      baseMarketStructure.forEach((bar, i) => {\n        const isLast = i === count - 1;\n        const o = bar.o, c = isLast ? bar.c + liveOffset : bar.c;\n        const hVal = isLast ? Math.max(bar.h, c + 0.25) : bar.h, lVal = isLast ? Math.min(bar.l, c - 0.25) : bar.l;\n        const x = i * step + step * 0.6, yOpen = priceToY(o), yClose = priceToY(c), yHigh = priceToY(hVal), yLow = priceToY(lVal);\n        const bull = c >= o, col = bull ? tvGreen : tvRed;\n\n        const volH = (bar.v / 130) * 22;\n        indCtx.fillStyle = bull ? 'rgba(38,166,154,0.15)' : 'rgba(239,83,80,0.15)';\n        indCtx.fillRect(x - step * 0.3, h - volH, step * 0.6, volH);\n\n        indCtx.strokeStyle = col; indCtx.lineWidth = 1.15;\n        indCtx.beginPath(); indCtx.moveTo(x, yHigh); indCtx.lineTo(x, yLow); indCtx.stroke();\n        indCtx.fillStyle = col;\n        indCtx.fillRect(x - step * 0.32, Math.min(yOpen, yClose), step * 0.64, Math.max(2, Math.abs(yClose - yOpen)));\n\n        if (activeIndicatorIndex === 0 && i === 17) {\n          indCtx.fillStyle = '#D4AF37'; indCtx.fillRect(x - 26, yHigh - 18, 52, 12);\n          indCtx.fillStyle = '#030406'; indCtx.font = '700 8px \"JetBrains Mono\"'; indCtx.textAlign = 'center';\n          indCtx.fillText('\u25BC SWEEP', x, yHigh - 9); indCtx.textAlign = 'left';\n        }\n      });\n\n      const lastBar = baseMarketStructure[count - 1], liveClose = lastBar.c + liveOffset, liveY = priceToY(liveClose);\n      const tagCol = liveClose >= lastBar.o ? tvGreen : tvRed;\n      indCtx.save(); indCtx.setLineDash([2, 2]); indCtx.strokeStyle = tagCol; indCtx.beginPath(); indCtx.moveTo(0, liveY); indCtx.lineTo(chartW, liveY); indCtx.stroke(); indCtx.restore();\n      indCtx.fillStyle = tagCol; indCtx.fillRect(chartW, liveY - 8, rightAxisW, 16);\n      indCtx.fillStyle = '#FFF'; indCtx.font = '700 8.5px \"JetBrains Mono\"'; indCtx.fillText(liveClose.toFixed(1), chartW + 4, liveY + 3);\n\n      requestAnimationFrame(renderIndicatorChart);\n    }\n    renderIndicatorChart();\n\n    /* =====================================================================\n       6. CINEMATIC LOW-ORBIT EARTH HORIZON, CONTINENTS & SIGNAL ARROWS\n       (Recalibrated so the continents, city callout pills, and directional\n        signal transmission arrows sit prominently in the upper-middle view)\n    ===================================================================== */\n    const globeCanvas = document.getElementById('globeCanvas');\n    const globeCtx = globeCanvas.getContext('2d');\n    let globeYaw = 0.35; // Centers North Atlantic (Virginia, London, Frankfurt) right in the middle of the horizon\n    let targetYaw = null, isDraggingGlobe = false, prevMouseX = 0, horizonTick = 0;\n\n    // Detailed Continental Envelopes for Bright Stippled Landmasses\n    const continentPolygons = [\n      { latMin: 24, latMax: 62, lonMin: -128, lonMax: -60 }, // North America\n      { latMin: 12, latMax: 24, lonMin: -105, lonMax: -75 }, // Central America\n      { latMin: 50, latMax: 60, lonMin: -10, lonMax: 3 },    // UK & Ireland\n      { latMin: 36, latMax: 58, lonMin: -9, lonMax: 35 },    // Europe\n      { latMin: 58, latMax: 70, lonMin: 5, lonMax: 32 },     // Scandinavia\n      { latMin: 15, latMax: 35, lonMin: -17, lonMax: 55 },   // N. Africa & Middle East\n      { latMin: 22, latMax: 52, lonMin: 65, lonMax: 146 }    // Asia & Japan\n    ];\n\n    function isLandmass(lat, lon) {\n      for (let i = 0; i < continentPolygons.length; i++) {\n        const b = continentPolygons[i];\n        if (lat >= b.latMin && lat <= b.latMax && lon >= b.lonMin && lon <= b.lonMax) {\n          if (Math.sin(lat * 0.4) * Math.cos(lon * 0.3) > -0.7) return true;\n        }\n      }\n      return false;\n    }\n\n    const earthPoints = [];\n    for (let lat = -10; lat <= 80; lat += 1.7) {\n      const lonStep = 1.7 / Math.max(0.28, Math.cos((lat * Math.PI) / 180));\n      for (let lon = -180; lon < 180; lon += lonStep) {\n        const land = isLandmass(lat, lon);\n        if (land || (Math.abs(lat % 8) < 0.9 && Math.abs(lon % 8) < 0.9)) {\n          earthPoints.push({ lat, lon, land, size: land ? 1.65 : 0.9 });\n        }\n      }\n    }\n\n    // Well-separated Callout Pill Offsets so London & Frankfurt never overlap\n    const orbitalHubs = [\n      { code: 'NY4', title: 'Virginia, US', sub: 'SAMPLE', lat: 39.0, lon: -77.5, dotColor: '#38BDF8', pillDX: -55, pillDY: -62 },\n      { code: 'LD4', title: 'London, UK', sub: 'SAMPLE', lat: 51.5, lon: -0.1, dotColor: '#10B981', pillDX: -125, pillDY: -68 },\n      { code: 'FR2', title: 'Frankfurt, DE', sub: 'SAMPLE', lat: 50.1, lon: 10.5, dotColor: '#D4AF37', pillDX: 28, pillDY: -48 },\n      { code: 'TY3', title: 'Tokyo, JP', sub: 'SAMPLE', lat: 35.6, lon: 139.6, dotColor: '#22D3EE', pillDX: -70, pillDY: -58 }\n    ];\n\n    // Signal Transmission Routes with Multiple Moving Arrow Packets\n    const orbitalArcs = [\n      { from: 0, to: 1, progress: 0.18, speed: 0.0045, alt: 95, color: '#38BDF8' }, // Virginia -> London\n      { from: 0, to: 2, progress: 0.62, speed: 0.0040, alt: 120, color: '#F7E7B4' }, // Virginia -> Frankfurt\n      { from: 1, to: 2, progress: 0.40, speed: 0.0065, alt: 52, color: '#34D399' },  // London -> Frankfurt\n      { from: 2, to: 3, progress: 0.25, speed: 0.0042, alt: 110, color: '#22D3EE' }  // Frankfurt -> Tokyo\n    ];\n\n    globeCanvas.addEventListener('mousedown', e => { isDraggingGlobe = true; targetYaw = null; prevMouseX = e.clientX; });\n    window.addEventListener('mouseup', () => { isDraggingGlobe = false; });\n    window.addEventListener('mousemove', e => { if (isDraggingGlobe) { globeYaw += (e.clientX - prevMouseX) * 0.005; prevMouseX = e.clientX; } });\n\n    function focusGlobeRegion(idx, code, label, rtt) {\n      playTickSound(860);\n      // 0: London, 1: Virginia, 2: Frankfurt, 3: Tokyo\n      targetYaw = [0.48, 0.78, 0.35, -1.85][idx];\n      document.getElementById('globe-active-route').textContent = `ORBITAL LOCK: CLOUDFLARE EDGE \u21C4 ${label.toUpperCase()}`;\n      document.getElementById('globe-active-rtt').textContent = rtt;\n      [0, 1, 2, 3].forEach(i => {\n        document.getElementById('globe-btn-' + i).setAttribute('aria-pressed',String(i===idx));\n        document.getElementById('globe-btn-' + i).querySelector('div').className=i===idx?'text-gold-light font-semibold':'text-white font-semibold';\n        document.getElementById('globe-btn-' + i).className = i === idx\n          ? 'p-3.5 rounded-xl bg-gold/15 border border-gold text-left transition-all'\n          : 'p-3.5 rounded-xl bg-obsidian/80 border border-white/10 text-left hover:border-gold/40 transition-all';\n      });\n      showToast(`Orbital Camera Locked \u2192 ${label} (${rtt})`);\n    }\n\n    function projectEarthPoint(latDeg, lonDeg, cx, cy, R, pitchTilt) {\n      const lat = (latDeg * Math.PI) / 180;\n      const lon = (lonDeg * Math.PI) / 180 + globeYaw;\n      const x0 = R * Math.cos(lat) * Math.sin(lon);\n      const y0 = R * Math.sin(lat);\n      const z0 = R * Math.cos(lat) * Math.cos(lon);\n\n      const y1 = y0 * Math.cos(pitchTilt) - z0 * Math.sin(pitchTilt);\n      const z1 = y0 * Math.sin(pitchTilt) + z0 * Math.cos(pitchTilt);\n      return { sx: cx + x0, sy: cy - y1, z: z1 };\n    }\n\n    // Draws a glowing directional arrowhead oriented along the tangent angle\n    function drawSignalArrowhead(ctx, x, y, angle, color) {\n      ctx.save();\n      ctx.translate(x, y);\n      ctx.rotate(angle);\n      ctx.beginPath();\n      ctx.moveTo(7, 0);\n      ctx.lineTo(-5, -4.2);\n      ctx.lineTo(-2.5, 0);\n      ctx.lineTo(-5, 4.2);\n      ctx.closePath();\n      ctx.fillStyle = '#FFFFFF';\n      ctx.shadowColor = color;\n      ctx.shadowBlur = 12;\n      ctx.fill();\n      ctx.restore();\n    }\n\n    function renderHorizonGlobe() {\n      const rect = globeCanvas.getBoundingClientRect();\n      const pixelRatio = Math.min(window.devicePixelRatio || 1, 2);\n      const wpx = Math.round(rect.width * pixelRatio), hpx = Math.round(rect.height * pixelRatio);\n      if(globeCanvas.width !== wpx || globeCanvas.height !== hpx){\n        globeCanvas.width = wpx; globeCanvas.height = hpx;\n        globeCtx.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);\n      }\n\n      const w = rect.width, h = rect.height;\n      horizonTick += 0.025;\n\n      if (targetYaw !== null) {\n        globeYaw += (targetYaw - globeYaw) * 0.065;\n        if (Math.abs(targetYaw - globeYaw) < 0.002) targetYaw = null;\n      } else if (!isDraggingGlobe) {\n        globeYaw += 0.00055;\n      }\n\n      globeCtx.clearRect(0, 0, w, h);\n\n      // Recalibrated Sphere Geometry so the lit Earth fills the lower 75% of the viewport\n      // and the cities sit right in the middle of the canvas!\n      const R = Math.max(w, h) * 0.88;\n      const cx = w * 0.50;\n      const cy = h * 0.24 + R;\n      const pitchTilt = 0.22; // Brings Latitudes 35N-55N right into the prime upper-middle view\n\n      // 1. Bright Atmospheric Horizon Halo (Like Reference Video)\n      const limbGrad = globeCtx.createRadialGradient(cx, cy, R * 0.88, cx, cy, R * 1.15);\n      limbGrad.addColorStop(0, 'rgba(10, 25, 58, 1)');\n      limbGrad.addColorStop(0.48, 'rgba(22, 78, 175, 0.55)');\n      limbGrad.addColorStop(0.64, 'rgba(56, 189, 248, 0.32)');\n      limbGrad.addColorStop(0.80, 'rgba(212, 175, 55, 0.08)');\n      limbGrad.addColorStop(1, 'transparent');\n      globeCtx.fillStyle = limbGrad;\n      globeCtx.beginPath(); globeCtx.arc(cx, cy, R * 1.15, 0, Math.PI * 2); globeCtx.fill();\n\n      // 2. Illuminated Planetary Surface Body\n      const coreGrad = globeCtx.createRadialGradient(cx, cy - R * 0.78, R * 0.05, cx, cy, R);\n      coreGrad.addColorStop(0, '#0C224A');\n      coreGrad.addColorStop(0.42, '#061229');\n      coreGrad.addColorStop(0.85, '#030813');\n      coreGrad.addColorStop(1, '#020408');\n      globeCtx.beginPath(); globeCtx.arc(cx, cy, R, 0, Math.PI * 2); globeCtx.fillStyle = coreGrad; globeCtx.fill();\n\n      // 3. Crisp Glowing Horizon Curvature Rim\n      globeCtx.beginPath(); globeCtx.arc(cx, cy, R, Math.PI * 1.12, Math.PI * 1.88);\n      globeCtx.strokeStyle = 'rgba(125, 211, 252, 0.75)'; globeCtx.lineWidth = 2; globeCtx.stroke();\n\n      // 4. Render Stippled Continents & Ocean Graticule Dots\n      earthPoints.forEach(pt => {\n        const proj = projectEarthPoint(pt.lat, pt.lon, cx, cy, R, pitchTilt);\n        if (proj.z > 0 && proj.sy < h + 10 && proj.sx > -10 && proj.sx < w + 10) {\n          const depth = Math.min(1, (proj.z / R) * 1.35);\n          globeCtx.fillStyle = pt.land\n            ? `rgba(147, 197, 253, ${depth * 0.85})`\n            : `rgba(148, 163, 184, ${depth * 0.22})`;\n          globeCtx.beginPath(); globeCtx.arc(proj.sx, proj.sy, pt.size, 0, Math.PI * 2); globeCtx.fill();\n        }\n      });\n\n      // 5. Project Data Center Cities\n      const visHubs = orbitalHubs.map(hub => {\n        const proj = projectEarthPoint(hub.lat, hub.lon, cx, cy, R, pitchTilt);\n        return { ...hub, ...proj, visible: proj.z > R * 0.05 };\n      });\n\n      // 6. Render High-Visibility Signal Transmission Arcs & Directional Arrows\n      orbitalArcs.forEach(arc => {\n        arc.progress = (arc.progress + arc.speed) % 1;\n        const A = visHubs[arc.from], B = visHubs[arc.to];\n        if (A.visible && B.visible) {\n          const midX = (A.sx + B.sx) / 2;\n          const midY = Math.min(A.sy, B.sy) - arc.alt;\n\n          // Base dashed orbital trajectory guide\n          globeCtx.save();\n          globeCtx.setLineDash([4, 4]);\n          globeCtx.beginPath(); globeCtx.moveTo(A.sx, A.sy); globeCtx.quadraticCurveTo(midX, midY, B.sx, B.sy);\n          globeCtx.strokeStyle = 'rgba(148, 163, 184, 0.35)'; globeCtx.lineWidth = 1.3; globeCtx.stroke();\n          globeCtx.restore();\n\n          // Helper for Quadratic Bezier position & tangent angle\n          const getArcPt = u => ({\n            x: (1 - u) * (1 - u) * A.sx + 2 * (1 - u) * u * midX + u * u * B.sx,\n            y: (1 - u) * (1 - u) * A.sy + 2 * (1 - u) * u * midY + u * u * B.sy\n          });\n\n          // Render two staggered signal arrows along each active route\n          [0, 0.5].forEach(offset => {\n            const t = (arc.progress + offset) % 1;\n            const head = getArcPt(t);\n            const prev = getArcPt(Math.max(0, t - 0.02));\n            const angle = Math.atan2(head.y - prev.y, head.x - prev.x);\n\n            // Luminous Comet Trail behind the Arrowhead\n            const tailStart = getArcPt(Math.max(0, t - 0.18));\n            const tailGrad = globeCtx.createLinearGradient(tailStart.x, tailStart.y, head.x, head.y);\n            tailGrad.addColorStop(0, 'transparent');\n            tailGrad.addColorStop(1, arc.color);\n\n            globeCtx.beginPath();\n            globeCtx.moveTo(tailStart.x, tailStart.y);\n            globeCtx.quadraticCurveTo(\n              getArcPt(Math.max(0, t - 0.09)).x,\n              getArcPt(Math.max(0, t - 0.09)).y,\n              head.x,\n              head.y\n            );\n            globeCtx.strokeStyle = tailGrad;\n            globeCtx.lineWidth = 2.6;\n            globeCtx.stroke();\n\n            // Crisp Directional Arrowhead\n            drawSignalArrowhead(globeCtx, head.x, head.y, angle, arc.color);\n          });\n        }\n      });\n\n      // 7. Surface Radar Beacons & Non-Overlapping City Callout Pills\n      visHubs.forEach(hNode => {\n        if (!hNode.visible) return;\n        const pulseR = 6 + (horizonTick * 9) % 22;\n        const pulseAlpha = 1 - ((pulseR - 6) / 22);\n\n        // Surface Concentric Radar Rings\n        globeCtx.beginPath(); globeCtx.arc(hNode.sx, hNode.sy, pulseR, 0, Math.PI * 2);\n        globeCtx.strokeStyle = `rgba(56, 189, 248, ${pulseAlpha * 0.85})`; globeCtx.lineWidth = 1.5; globeCtx.stroke();\n\n        globeCtx.beginPath(); globeCtx.arc(hNode.sx, hNode.sy, 4.2, 0, Math.PI * 2);\n        globeCtx.fillStyle = '#FFFFFF'; globeCtx.shadowColor = hNode.dotColor; globeCtx.shadowBlur = 14; globeCtx.fill(); globeCtx.shadowBlur = 0;\n\n        // Frosted Glass Callout Pill with Leader Line\n        const pillW = 148, pillH = 28;\n        const pillX = Math.max(12, Math.min(w - pillW - 12, hNode.sx + hNode.pillDX));\n        const pillY = Math.max(14, Math.min(h - pillH - 18, hNode.sy + hNode.pillDY));\n\n        // Leader Line\n        globeCtx.beginPath();\n        globeCtx.moveTo(hNode.sx, hNode.sy);\n        globeCtx.lineTo(pillX + pillW * 0.5, pillY + pillH * 0.5);\n        globeCtx.strokeStyle = 'rgba(148, 163, 184, 0.55)';\n        globeCtx.lineWidth = 1.2;\n        globeCtx.stroke();\n\n        // Pill Box\n        globeCtx.fillStyle = 'rgba(7, 11, 20, 0.92)';\n        globeCtx.strokeStyle = 'rgba(255, 255, 255, 0.22)';\n        globeCtx.lineWidth = 1.1;\n        globeCtx.beginPath();\n        globeCtx.roundRect(pillX, pillY, pillW, pillH, 7);\n        globeCtx.fill();\n        globeCtx.stroke();\n\n        // Status Dot inside Pill\n        globeCtx.beginPath();\n        globeCtx.arc(pillX + 12, pillY + pillH / 2, 3.5, 0, Math.PI * 2);\n        globeCtx.fillStyle = hNode.dotColor;\n        globeCtx.fill();\n\n        // City Name & RTT Latency\n        globeCtx.fillStyle = '#FFFFFF';\n        globeCtx.font = '600 10.5px \"Plus Jakarta Sans\"';\n        globeCtx.textAlign = 'left';\n        globeCtx.fillText(hNode.title, pillX + 22, pillY + 17.5);\n\n        globeCtx.fillStyle = '#34D399';\n        globeCtx.font = '600 9px \"JetBrains Mono\"';\n        globeCtx.textAlign = 'right';\n        globeCtx.fillText(hNode.sub, pillX + pillW - 8, pillY + 17.5);\n      });\n\n      requestAnimationFrame(renderHorizonGlobe);\n    }\n    renderHorizonGlobe();\n\n\nfunction openModal(id){if(id==='portal-modal')document.getElementById('loginOpen').click();else openAuth();}\nfunction toggleLanguage(){document.getElementById('lang').click();}\n";

