function once(html, find, replace) {
  if (!html.includes(find)) throw Error("SITE_COMPOSE_MISSING " + find.slice(0, 40));
  return html.replace(find, () => replace);
}
var BASE_HTML = DESIGN_HTML.replace(/<button id="runConnectionCheck"[^>]*>[^<]*<\/button>/, '<span id="runConnectionCheck" hidden></span>').replace(/<button id="runDemoTrade"[^>]*>[^<]*<\/button>/, '<span id="runDemoTrade" hidden></span>' + EXECUTION_HTML);
var composed = BASE_HTML;
composed = composed.replace(/<a href="#plans" onmouseenter="playTickSound\(880\)"([\s\S]*?)<\/a>/, (_, body) => '<button id="heroBridgeFree" type="button" data-plan="trial" onmouseenter="playTickSound(880)"' + body + "</button>");
composed = composed.replace('<button onclick="triggerManualSignalPulse()"', '<button id="heroScalperFree" type="button" data-sx-open="scalper"');
composed = composed.replace(/(data-i18n="cta_explore">)[^<]*/, "$1Get Signal Bridge Free").replace(/(data-i18n="cta_simulate">)[^<]*/, "$1Get Scalper Pro Free");
composed = once(composed, "  <!-- NAVIGATION -->", SX_ANNOUNCE_HTML + "  <!-- NAVIGATION -->");
composed = once(composed, '<a href="#plans" onmouseenter="playTickSound(750)"', NAV_LINK + '<a href="#plans" onmouseenter="playTickSound(750)"');
composed = once(composed, '<a class="block py-2" href="#plans"', '<a class="block py-2" href="#scalper">Scalper Pro <span class="sx-sbtab-new">NEW</span></a><a class="block py-2" href="#plans"');
composed = composed.replace(/(data-i18n="hero_desc">)[^<]*/, (m, a) => a + "\n          " + HERO_DESC + "\n        ");
composed = once(composed, '<section id="product-gallery"', SX_SUITE_HTML + '  <section id="product-gallery"');
composed = once(composed, '  <section id="plans"', SX_SCALPER_HTML + '  <section id="plans"');
composed = once(composed, '<button data-sb-tab="settings">\u2699 Settings</button></nav>', '<button data-sb-tab="settings">\u2699 Settings</button><button data-sb-tab="scalper">\u25CE Scalper Pro<span class="sx-sbtab-new">NEW</span></button></nav>');
composed = once(composed, '<button data-sb-tab="settings">\u2699<span>Settings</span></button></div>', '<button data-sb-tab="settings">\u2699<span>Settings</span></button><button data-sb-tab="scalper">\u25CE<span>Scalper</span><i class="sx-sbtab-new">NEW</i></button></div>');
composed = once(composed, '<div class="portal-checkout">', SX_PORTAL_SCALPER_HTML + '<div class="portal-checkout">');
composed = once(composed, '<div class="toast hidden" role="status" id="toast"></div>', SX_MOBILE_CTA_HTML + '<div class="toast hidden" role="status" id="toast"></div>');
var legacyAccountActions = /<button id="loginOpen"[\s\S]*?<\/button>\s*<button onclick="openModal\('auth-modal'\)"[\s\S]*?<\/button>/;
if (!legacyAccountActions.test(composed)) throw Error("ACCOUNT_ACTIONS_NOT_FOUND");
composed = composed.replace(legacyAccountActions, () => '<div class="drfx-desktop-account-actions" role="group" aria-label="Account access">\n          <button id="loginOpen" type="button" class="drfx-account-cta drfx-account-cta--auth" aria-label="Sign in or sign up"><span>Sign In / Sign Up</span><span aria-hidden="true">\u2197</span></button>\n          <button id="clientPortalOpen" type="button" class="drfx-account-cta drfx-account-cta--portal" aria-label="Open DrFX Client Portal"><span class="drfx-portal-online" aria-hidden="true"></span><span>Client Portal</span><span aria-hidden="true">\u2197</span></button>\n        </div>');
composed = once(composed, '</header>\n  <nav id="mobileNav"', '</header>\n  <div class="drfx-mobile-account-actions" role="group" aria-label="DrFX account access">\n      <button id="mobileAuthOpen" type="button" class="drfx-account-cta drfx-account-cta--auth" aria-label="Sign in or sign up"><span>Sign In / Sign Up</span><span aria-hidden="true">\u2197</span></button>\n      <button id="mobilePortalOpen" type="button" class="drfx-account-cta drfx-account-cta--portal" aria-label="Open DrFX Client Portal"><span class="drfx-portal-online" aria-hidden="true"></span><span>Client Portal</span><span aria-hidden="true">\u2197</span></button>\n    </div>\n  <nav id="mobileNav"');
