async function checkout(plan){
 if(plan!=='trial'&&readiness.payments===false){notice('Paid checkout is not enabled yet. No payment was requested.');return;}
 if(!state.user){state.plan=plan;openAuth();return;}
 if(plan==='trial'){await openPortal();return;}
 try{const p=await call('/api/checkout','POST',{plan});const url=new URL(p.invoice_url);
  if(url.protocol!=='https:'||!(url.hostname==='nowpayments.io'||url.hostname.endsWith('.nowpayments.io')))throw Error('INVALID_GATEWAY_URL');
  location.assign(url.href);
 }catch(e){notice(e.message==='PAYMENTS_NOT_CONFIGURED'?'Secure payments will open after merchant verification.':localeError(e));}
}
const accountAuthAction=()=>{if(state.user)openPortal();else openAuth();};
const accountPortalAction=()=>openPortal();
for(const id of ['loginOpen','mobileAuthOpen'])$(id).addEventListener('click',accountAuthAction);
for(const id of ['clientPortalOpen','mobilePortalOpen'])$(id).addEventListener('click',accountPortalAction);
