const emailSendFeedback=document.createElement('div');
emailSendFeedback.id='emailSendFeedback';
emailSendFeedback.className='email-send-feedback';
emailSendFeedback.setAttribute('role','status');
emailSendFeedback.setAttribute('aria-live','polite');
emailSendFeedback.setAttribute('aria-atomic','true');
