$('sendEmail').onclick=async()=>{
 const email=$('email').value.trim();
 const button=$('sendEmail'),label=button.querySelector('[data-i18n="sendCode"]');
 if(button.disabled)return;
 if(!$('email').checkValidity()||!email){showEmailFeedback('error','Enter a valid email address.');$('email').focus();return;}
 const original=label?.textContent||'Send sign-in code';
 button.disabled=true;
 button.classList.add('email-send-busy');
 if(label)label.textContent='Sending\u2026';
 showEmailFeedback('sending','Sending your secure code\u2026');
 try{
  await call('/api/auth/email/start','POST',{email});
  showEmailFeedback('sent','Code sent! Check your inbox or Spam folder. Enter it below to continue.');
  status('authMsg','Your sign-in code has been sent. It expires in 10 minutes.');
  if(label)label.textContent='Resend code';
  $('emailCode').focus();
 }catch(e){
  const msg=e.message==='EMAIL_NOT_CONFIGURED'?'Email sign-in is temporarily unavailable.':
   e.message==='RATE_LIMITED'?'Too many requests. Please try again later.':
   localeError(e);
  showEmailFeedback('error',msg);
  status('authMsg',msg,true);
  if(label)label.textContent=original;
 }finally{
  button.classList.remove('email-send-busy');
  button.disabled=readiness.email===false;
 }
};
$('verifyEmail').onclick=async()=>{
 try{await call('/api/auth/email/verify','POST',{email:$('email').value.trim(),code:$('emailCode').value.trim()});await openPortal();}
 catch(e){status('authMsg',localeError(e),true);}
};
// 32-character reusable password from /login; 16-char legacy codes accepted only until expiry.
function validateWebsiteLoginCode(){
 const code=$('tgCode').value.trim();
 const permanent=code.length===32&&/^[A-Za-z0-9_-]{32}$/.test(code);
 const legacy=code.length===16&&/^[A-Za-z0-9_-]{16}$/.test(code);
 let hint='Request /login from your Signal Bridge bot. Your 32-character website code stays valid until you reset it.';
 if(code.length===43)hint='This is a 43-character MT5 EA activation serial from /code, not a website password.';
 else if(code.length&&!(permanent||legacy))hint='Enter the permanent 32-character website code received using /login.';
 else if(permanent)hint='Permanent website code format is valid. It can be reused for future sign-ins.';
 else if(legacy)hint='Legacy one-time code format detected. Old codes still expire after 10 minutes; use /login for the new permanent code.';
 $('tgCodeHint').textContent=hint;
 $('tgCodeHint').classList.toggle('invalid',code.length>0&&!(permanent||legacy));
 $('loginTelegram').disabled=!(permanent||legacy);
 return permanent||legacy?code:null;
}
$('tgCode').addEventListener('input',validateWebsiteLoginCode);
$('tgCode').addEventListener('keydown',e=>{if(e.key==='Enter'&&!$('loginTelegram').disabled)$('loginTelegram').click();});
$('loginTelegram').onclick=async()=>{
 const code=validateWebsiteLoginCode();
 if(!code){status('authMsg','Use your 32-character permanent website code from /login, not your EA serial.',true);return;}
 $('loginTelegram').disabled=true;
 try{
  await call('/api/auth/telegram/code','POST',{code});
  $('tgCode').value='';
  await openPortal();
 }catch(e){
  const guidance={
   EA_CODE_NOT_LOGIN_CODE:'Your /code serial activates MT5 only. Request your reusable website code with /login.',
   INVALID_LOGIN_CODE_FORMAT:'Enter your 32-character permanent website code from /login.',
   INVALID_LOGIN_CREDENTIAL:'This code is not valid. Request /login in your Telegram bot; if you rotated it, use the newest code.',
   INVALID_OR_EXPIRED_CODE:'Old one-time code expired; use /login for the reusable credential.',
   RATE_LIMITED:'Too many attempts. Try again later.'
  };
  status('authMsg',guidance[e.message]||localeError(e),true);
 }finally{validateWebsiteLoginCode();}
};
