// Shared language interface. English remains the default.
const i18n=window.DrFXI18N||{languages:['en'],text:{en:{}}};
const siteEnglish=new Map();
document.querySelectorAll('[data-i], [data-i18n]').forEach(el=>siteEnglish.set(el,el.textContent));
const selectLanguage=lang=>{
 const next=i18n.languages.includes(lang)?lang:'en';
 state.lang=next;
 document.documentElement.lang=next;
 document.documentElement.dir=next==='fa'?'rtl':'ltr';
 document.body.dir=document.documentElement.dir;
 const t=i18n.text[next]||{};
 for(const [el,englishText] of siteEnglish){
  const key=(el.dataset.i18n||el.dataset.i||'').replaceAll('-','_');
  el.textContent=t[key]||(next==='fa'?tr.fa[el.dataset.i]:null)||englishText;
 }
 document.querySelectorAll('[data-i18n-attr-aria-label],[data-i18n-attr-title],[data-i18n-attr-placeholder]').forEach(el=>{
  for(const attr of ['aria-label','title','placeholder']){
   const key=el.getAttribute('data-i18n-attr-'+attr);
   if(key)el.setAttribute(attr,t[key]||i18n.text.en?.[key]||el.getAttribute(attr));
  }
 });
 $('siteLanguageCurrent').textContent=next.toUpperCase();
 $('siteLanguageOptions').querySelectorAll('[data-site-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.siteLanguage===next)));
 closeSiteLanguage();
 try{window.localStorage.setItem('drfx-language',next)}catch{}
 window.dispatchEvent(new CustomEvent('drfx-language-change',{detail:{lang:next}}));
};
const sitePicker=$('siteLanguagePicker'),siteOptions=$('siteLanguageOptions');
function closeSiteLanguage(){siteOptions.hidden=true;$('lang').setAttribute('aria-expanded','false');}
$('lang').addEventListener('click',()=>{const open=siteOptions.hidden;siteOptions.hidden=!open;$('lang').setAttribute('aria-expanded',String(open));});
siteOptions.querySelectorAll('[data-site-language]').forEach(b=>b.addEventListener('click',()=>selectLanguage(b.dataset.siteLanguage)));
document.addEventListener('click',e=>{if(!sitePicker.contains(e.target))closeSiteLanguage()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSiteLanguage()});
try{const saved=window.localStorage.getItem('drfx-language');if(i18n.languages.includes(saved))selectLanguage(saved);}catch{}
