const globeClips=[...document.querySelectorAll('[data-motion-video]')];
const prefersReducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
if(!prefersReducedMotion.matches && !navigator.connection?.saveData){
 const globeObserver='IntersectionObserver' in window?new IntersectionObserver(entries=>{entries.forEach(entry=>{
  const v=entry.target;if(entry.isIntersecting && document.visibilityState==='visible'){
   if(!v.src)v.src=v.dataset.videoSource;
   v.play().catch(()=>{});
  }else v.pause();
 })},{rootMargin:'150px 0px',threshold:0.05}):null;
 globeClips.forEach(video=>{
  video.addEventListener('error',()=>{video.dataset.mediaUnavailable='true';video.pause()});
  if(globeObserver)globeObserver.observe(video);
  else{video.src=video.dataset.videoSource;video.play().catch(()=>{})}
 });
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')globeClips.forEach(v=>v.pause())});
 prefersReducedMotion.addEventListener('change',e=>{if(e.matches)globeClips.forEach(v=>v.pause())});
}



