async function connectionDiagnostic(env, user) {
  const row = await env.DB.prepare(
    "SELECT sl.agent_id,el.status,el.plan,el.activated_at,el.expires_at,el.account_login,el.account_server,a.status AS agent_status,a.last_connected_at FROM site_licenses sl JOIN ea_licenses el ON el.id=sl.license_id JOIN agent_connections a ON a.id=sl.agent_id WHERE sl.user_id=? LIMIT 1"
  ).bind(user.id).first();
  if (!row) return { license: "missing", mt5_bound: false, last_handshake: null, live_socket_verified: false, trade_executed: false };
  let live = false, terminal = false, connectedAt = null, snapshotAvailable = false, fresh = false, mt5Mode = null, capabilities = [], telemetry = null;
  if (env.AGENT_HUB) {
    try {
      const hub = env.AGENT_HUB.get(env.AGENT_HUB.idFromName(row.agent_id));
      const resp = await hub.fetch(new Request("https://agent-hub/snapshot"));
      if (resp.ok) {
        const state = await resp.json();
        snapshotAvailable = true;
        const socket = (state.clients || []).find((c) => c.agent_id === row.agent_id && c.client_type === "ea");
        const matches = !!socket && !!row.account_login && !!row.account_server && socket.account?.login === row.account_login && socket.account?.server === row.account_server;
        fresh = matches && Number.isFinite(Date.parse(socket.last_seen_at)) && Date.now() - Date.parse(socket.last_seen_at) >= 0 && Date.now() - Date.parse(socket.last_seen_at) < 9e4;
        live = matches && fresh;
        terminal = matches && socket.terminal_online === true && fresh;
        telemetry = matches ? socket.account : null;
        mt5Mode = matches ? socket.account?.mode : null;
        capabilities = matches ? socket.capabilities || [] : [];
        connectedAt = matches ? socket.connected_at || null : null;
      }
    } catch {
    }
  }
  return {
    agent_id: row.agent_id,
    license: row.status,
    agent_status: row.agent_status,
    plan: row.plan,
    mt5_bound: !!(row.account_login && row.account_server),
    mt5_account: row.account_login ? { login: row.account_login, server: row.account_server } : null,
    last_handshake: row.last_connected_at || null,
    activated_at: row.activated_at || null,
    live_socket_verified: live,
    terminal_online: terminal,
    live_snapshot_available: snapshotAvailable,
    expires_at: row.expires_at,
    telemetry: live ? telemetry : null,
    connected_at: connectedAt,
    fresh,
    mt5_mode: mt5Mode,
    capabilities,
    license_unexpired: !!row.expires_at && Date.parse(row.expires_at.replace(" ", "T") + "Z") > Date.now(),
    trade_executed: false,
    note: snapshotAvailable ? "Live Durable Object EA snapshot; no order was placed." : !env.AGENT_HUB ? "EA hub binding is missing from the site deployment." : "Live socket could not be independently verified. Database history shown only."
  };
}
