async function giftBridgeQuarter(env, admin, user, requestId) {
  if (!/^[0-9a-f]{32}$/.test(requestId || "")) return fail("INVALID_REQUEST_ID");
  const id = "gift_" + requestId, action = "gift_bridge_3m";
  const prior = () => env.DB.prepare("SELECT actor_id,subject_id,action FROM site_audit WHERE id=?").bind(id).first();
  const duplicate = (row) => row.actor_id === admin.id && row.subject_id === user.id && row.action === action ? json({ ok: true, duplicate: true }) : fail("REQUEST_ID_CONFLICT", 409);
  const existing = await prior();
  if (existing) return duplicate(existing);
  if (user.status !== "active") return fail("ACCOUNT_NOT_ACTIVE", 409);
  const license = await licenseRecord(env, user);
  const recorded = "EXISTS (SELECT 1 FROM site_audit WHERE id=? AND actor_id=? AND subject_id=? AND action='gift_bridge_3m')";
  const eligible = " AND EXISTS (SELECT 1 FROM site_users WHERE id=? AND status='active')";
  try {
    const [gift] = await env.DB.batch([
      env.DB.prepare("INSERT INTO site_audit (id,actor_id,action,subject_id,detail) SELECT ?,?,?,?,'+3 months' WHERE EXISTS (SELECT 1 FROM ea_licenses WHERE agent_id=? AND status='active')" + eligible).bind(id, admin.id, action, user.id, license.agent_id, user.id),
      env.DB.prepare("UPDATE ea_licenses SET plan=CASE WHEN plan='annual' THEN plan ELSE 'quarterly' END,duration_modifier=CASE WHEN activated_at IS NOT NULL THEN duration_modifier WHEN plan='trial' AND duration_modifier='+1 month' THEN '+3 months' WHEN duration_modifier='+1 year' THEN '+15 months' ELSE printf('+%d months',CAST(duration_modifier AS INTEGER)+3) END,expires_at=CASE WHEN activated_at IS NULL THEN NULL ELSE datetime(CASE WHEN expires_at>CURRENT_TIMESTAMP THEN expires_at ELSE CURRENT_TIMESTAMP END,'+3 months') END,updated_at=CURRENT_TIMESTAMP WHERE agent_id=? AND status='active' AND " + recorded + eligible).bind(license.agent_id, id, admin.id, user.id, user.id),
      env.DB.prepare("UPDATE site_users SET plan=(SELECT plan FROM ea_licenses WHERE agent_id=?),updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='active' AND " + recorded).bind(license.agent_id, user.id, id, admin.id, user.id)
    ]);
    if (gift.meta?.changes !== 1) return fail("LICENSE_NOT_ACTIVE", 409);
  } catch (error) {
    const row = await prior();
    if (row) return duplicate(row);
    throw error;
  }
  let notification = "unavailable";
  if (user.telegram_id && env.TELEGRAM_BOT_TOKEN) {
    try {
      const fa = await userBotLocale(env, user.telegram_id) === "fa";
      await botSend(env, user.telegram_id, fa ? "\u0627\u062F\u0645\u06CC\u0646 \u0633\u0647 \u0645\u0627\u0647 \u0644\u0627\u06CC\u0633\u0646\u0633 \u0631\u0627\u06CC\u06AF\u0627\u0646 \u0633\u06CC\u06AF\u0646\u0627\u0644 \u0628\u0631\u06CC\u062C \u0628\u0647 \u062D\u0633\u0627\u0628 \u0634\u0645\u0627 \u0627\u0636\u0627\u0641\u0647 \u06A9\u0631\u062F." : "An administrator added a complimentary three-month Signal Bridge license to your account.");
      notification = "sent";
    } catch {
      notification = "failed";
    }
  }
  return json({ ok: true, notification });
}
async function adminUpdate(req, env, admin) {
  const b = await readBody(req);
  if (!ADMIN_ACTIONS.has(b.action) || !/^usr_[0-9a-f]{32}$/.test(b.user_id || "")) return fail("INVALID_ACTION");
  const user = await env.DB.prepare("SELECT * FROM site_users WHERE id=?").bind(b.user_id).first();
  if (!user) return fail("NOT_FOUND", 404);
  if (user.id === admin.id && (b.action === "suspend" || b.action === "revoke_license")) return fail("SELF_LOCKOUT_REFUSED", 409);
  if (b.action === "gift_bridge_3m") return giftBridgeQuarter(env, admin, user, b.request_id);
  if (b.action.startsWith("grant_scalper_")) {
    try {
      const k = await scalperGrant(env, scalperHelpers(env), { adminId: admin.id, userId: user.id, login: b.account_login, plan: b.action.slice(6) });
      return json({ ok: true, scalper: k });
    } catch (e) {
      return fail(e.message === "INVALID_MT5_ACCOUNT" || e.message === "INVALID_PLAN" ? e.message : "SCALPER_LICENSING_NOT_CONFIGURED", e.message === "SCALPER_LICENSING_NOT_CONFIGURED" ? 503 : 400);
    }
  }
  if (b.action.startsWith("grant_")) {
    await licenseRecord(env, user);
    await applyPlan(env, user.id, b.action.slice(6), admin.id);
  } else if (b.action === "suspend" || b.action === "resume") {
    const status = b.action === "suspend" ? "suspended" : "active";
    await env.DB.batch([
      env.DB.prepare("UPDATE site_users SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(status, user.id),
      env.DB.prepare("UPDATE ea_licenses SET status=?,updated_at=CURRENT_TIMESTAMP WHERE agent_id=(SELECT agent_id FROM site_licenses WHERE user_id=?)").bind(b.action === "suspend" ? "revoked" : "active", user.id)
    ]);
    await audit(env, admin.id, b.action, user.id);
  } else if (b.action === "revoke_license") {
    await env.DB.prepare("UPDATE ea_licenses SET status='revoked',updated_at=CURRENT_TIMESTAMP WHERE agent_id=(SELECT agent_id FROM site_licenses WHERE user_id=?)").bind(user.id).run();
    await audit(env, admin.id, b.action, user.id);
  }
  return json({ ok: true });
}
async function createCheckout(req, env, user) {
  if (!env.NOWPAYMENTS_API_KEY || !env.NOWPAYMENTS_IPN_SECRET) return fail("PAYMENTS_NOT_CONFIGURED", 503);
  if (!await limited(req, env, "checkout", 8)) return fail("RATE_LIMITED", 429);
  const b = await readBody(req), plan = String(b.plan || "");
  if (!Object.hasOwn(PRICES, plan)) return fail("INVALID_PLAN");
  const id = uid("ord"), usd = PRICES[plan];
  await env.DB.prepare("INSERT INTO site_orders (id,user_id,plan,amount_usd,status) VALUES (?,?,?,?,'pending')").bind(id, user.id, plan, usd).run();
  const response = await fetch("https://api.nowpayments.io/v1/invoice", { method: "POST", headers: { "x-api-key": env.NOWPAYMENTS_API_KEY, "content-type": "application/json" }, body: JSON.stringify({
    price_amount: usd,
    price_currency: "usd",
    order_id: id,
    order_description: "DrFX Company " + plan + " membership",
    ipn_callback_url: API_ORIGIN + "/api/payments/ipn",
    success_url: API_ORIGIN + "/?paid=processing",
    cancel_url: API_ORIGIN + "/?paid=cancelled"
  }) });
  if (!response.ok) {
    await env.DB.prepare("UPDATE site_orders SET status='failed' WHERE id=?").bind(id).run();
    return fail("PAYMENT_GATEWAY_UNAVAILABLE", 502);
  }
  const data = await response.json().catch(() => null);
  let url;
  try {
    url = new URL(data?.invoice_url || "");
    if (url.protocol !== "https:" || !(url.hostname === "nowpayments.io" || url.hostname.endsWith(".nowpayments.io"))) throw Error("bad");
  } catch {
    await env.DB.prepare("UPDATE site_orders SET status='failed' WHERE id=?").bind(id).run();
    return fail("INVALID_GATEWAY_RESPONSE", 502);
  }
  await env.DB.prepare("UPDATE site_orders SET invoice_id=?,invoice_url=? WHERE id=?").bind(String(data.id || ""), url.href, id).run();
  return json({ ok: true, invoice_url: url.href, order_id: id });
}
function deepSort(value) {
  if (Array.isArray(value)) return value.map(deepSort);
  if (value && typeof value === "object") return Object.fromEntries(Object.keys(value).sort().map((k) => [k, deepSort(value[k])]));
  return value;
}
async function ipnHandler(req, env) {
  if (!env.NOWPAYMENTS_IPN_SECRET) return fail("PAYMENTS_NOT_CONFIGURED", 503);
  const signature = req.headers.get("x-nowpayments-sig") || "";
  if (!/^[a-f0-9]{128}$/i.test(signature)) return fail("INVALID_SIGNATURE", 401);
  const body = await readBody(req, 8192);
  const key = await crypto.subtle.importKey("raw", encoder2.encode(env.NOWPAYMENTS_IPN_SECRET), { name: "HMAC", hash: "SHA-512" }, false, ["sign"]);
  const signatureHex = Array.from(new Uint8Array(await crypto.subtle.sign("HMAC", key, encoder2.encode(JSON.stringify(deepSort(body))))), (b) => b.toString(16).padStart(2, "0")).join("");
  if (!safeEq(signature.toLowerCase(), signatureHex)) return fail("INVALID_SIGNATURE", 401);
  if (body.payment_status !== "finished") return json({ ok: true, ignored: "NOT_FINAL" });
  const orderId = String(body.order_id || ""), paymentId = String(body.payment_id || "");
  if (orderId.startsWith("sco_")) return scalperPaid(env, scalperHelpers(env), body);
  const order = await env.DB.prepare("SELECT * FROM site_orders WHERE id=?").bind(orderId).first();
  if (!order || order.status === "failed") return fail("ORDER_NOT_FOUND", 404);
  if (order.status === "paid") return json({ ok: true, duplicate: true });
  if (String(body.price_currency || "").toLowerCase() !== "usd" || Number(body.price_amount) !== Number(order.amount_usd) || !paymentId) return fail("PAYMENT_DETAILS_MISMATCH", 409);
  const lic = await env.DB.prepare("SELECT agent_id FROM site_licenses WHERE user_id=?").bind(order.user_id).first();
  if (!lic) return fail("LICENSE_MISSING", 503);
  const results = await env.DB.batch([
    env.DB.prepare("UPDATE ea_licenses SET plan=?,duration_modifier=?,status='active',expires_at=CASE WHEN activated_at IS NULL THEN NULL ELSE datetime(CASE WHEN expires_at>CURRENT_TIMESTAMP THEN expires_at ELSE CURRENT_TIMESTAMP END, ?) END,updated_at=CURRENT_TIMESTAMP WHERE agent_id=? AND EXISTS(SELECT 1 FROM site_orders WHERE id=? AND status='pending')").bind(order.plan, DURATION[order.plan], DURATION[order.plan], lic.agent_id, orderId),
    env.DB.prepare("UPDATE site_users SET plan=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND EXISTS(SELECT 1 FROM site_orders WHERE id=? AND status='pending')").bind(order.plan, order.user_id, orderId),
    env.DB.prepare("INSERT INTO site_audit (id,actor_id,action,subject_id,detail) SELECT ?,NULL,'nowpayments_paid',?,? WHERE EXISTS(SELECT 1 FROM site_orders WHERE id=? AND status='pending')").bind(uid("aud"), order.user_id, orderId, orderId),
    env.DB.prepare("UPDATE site_orders SET status='paid',payment_id=?,paid_at=CURRENT_TIMESTAMP WHERE id=? AND status='pending'").bind(paymentId, orderId)
  ]);
  return results[3]?.meta?.changes === 1 ? json({ ok: true, granted: true }) : json({ ok: true, duplicate: true });
}
async function botSend(env, chatId, text, keyboard, section) {
  if (!env.TELEGRAM_BOT_TOKEN) return;
  const body = { chat_id: chatId, text, parse_mode: "HTML", disable_web_page_preview: true };
  if (keyboard === true) body.reply_markup = { inline_keyboard: [[{ text: "Open DrFX Mini App", web_app: { url: API_ORIGIN + "/telegram" } }], [{ text: "Open website", url: API_ORIGIN }]] };
  else if (keyboard && typeof keyboard === "object") body.reply_markup = keyboard;
  return sendBotNotice(env, { raw: telegramWidgetApi, language: await userBotLocale(env, chatId) }, chatId, text, body.reply_markup, section);
}
async function telegramWidgetApi(env, method, body) {
  const response = await fetch("https://api.telegram.org/bot" + env.TELEGRAM_BOT_TOKEN + "/" + method, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(8e3)
  });
  const payload = await response.json().catch(() => ({ ok: false }));
  if (!response.ok || payload.ok !== true) throw Error("Telegram widget API failed: " + method);
  return payload.result;
}
var widgetSetupLast = 0;
async function reconcileWidgetBot(env) {
  if (!env.TELEGRAM_BOT_TOKEN || !env.TELEGRAM_WEBHOOK_SECRET) return;
  if (Date.now() - widgetSetupLast < 36e5) return;
  const target = "https://drfx.company/api/telegram/webhook";
  const current = await telegramWidgetApi(env, "getWebhookInfo", {});
  const existing = Array.isArray(current?.allowed_updates) ? current.allowed_updates : [];
  if (current?.url !== target || !existing.includes("widget_query") || !existing.includes("pre_checkout_query")) {
    const allowed = [...new Set([...existing, "message", "callback_query", "widget_query", "my_chat_member"].concat("pre_checkout_query"))];
    await telegramWidgetApi(env, "setWebhook", {
      url: target,
      secret_token: env.TELEGRAM_WEBHOOK_SECRET,
      allowed_updates: allowed,
      drop_pending_updates: false,
      max_connections: 10
    });
  }
  await telegramWidgetApi(env, "setMyCommands", { commands: BOT_COMMANDS_VISIBLE });
  await telegramWidgetApi(env, "setChatMenuButton", { menu_button: { type: "default" } });
  widgetSetupLast = Date.now();
}
