    let out = "\u26A1 <b>DrFX Scalper Pro</b>\nThe AI liquidity radar for XAUUSD on MT5. 7 days free inside the EA, then " + Object.keys(STAR_PLANS).filter((p) => p.startsWith("scalper_")).map((p) => STAR_PLANS[p].label + " \xB7 " + starPrice(env, p) + " Stars").join(" \xB7 ") + ".\n";
